/* ===== 第 2 章 錠劑（拍攝第 12～21 頁）===== */
ch(2, "錠劑", "12～21");
t(2, "錠劑", 12, "tablet-basics", "錠劑：簡介、製作、添加", "錠劑概論", [
  "簡介：日常生活中{{最常用|性質}}劑型",
  "製作：原料藥加上{{賦形劑|名詞}}（稀釋劑、潤滑劑、黏合劑、崩散劑等），經打錠壓製而成",
  "添加：可加入{{糖衣、腸衣或膜衣|名詞}}等，製成不同製劑",
  "機器：可用{{噴霧乾燥機|名詞}}將藥物包衣（噴霧目的：可獲得{{較大表面積|名詞}}）；外型：{{橢圓形|名詞}}較易吞服"
]);
t(2, "錠劑", 12, "tablet-coating", "著衣（包衣）的目的", "著衣目的", [
  "1. 防止調劑者接觸（如 {{Finasteride|藥名}}（Proscar®）需避免已懷孕或計畫懷孕之藥師或病人接觸，可能導致{{男性胎兒畸形|副作用}}）",
  "2. 保護有效成分對{{光線、水氣以及空氣|名詞}}之安定",
  "3. {{掩蓋藥品不良氣味|名詞}}、改善外觀、降低粉塵等",
  "4. 最常見膜衣由{{纖維素聚合物|物質}}所組成，糖衣為其中一種替代方法（較不常見）",
  "5. 糖衣錠具有較厚塗層，主要含有多種無機稀釋劑之{{蔗糖|物質}}",
  "6. 此類配方可保護對{{酸|名詞}}不穩定之藥品成分，降低在胃液中酸性環境之破壞，也可控制藥品於胃腸道之釋放速率，降低給藥頻率"
]);
t(2, "錠劑", 12, "tablet-pharmacopeia", "中華藥典（歷年曾考過內容）：錠劑", "藥典錠劑", [
  "厚度：{{±5%|數值}} 以內",
  "重量：{{脆度分析|名詞}}之損失應不得超過 {{1%|數值}}",
  "硬度：{{4-5 公斤|數值}}（藥廠業界經驗值，並非藥典統一規範）",
  "壓錠：壓力約 {{3000-4000 磅|數值}}",
  "乾燥減重：取錠劑粉末不少於 {{4|數值}} 錠"
]);
t(2, "錠劑種類", 12, "coated-tablet", "一般著衣錠", "一般著衣錠", [
  "簡介：錠劑僅以{{糖液|物質}}，藉{{阿拉伯膠或明膠|物質}}使澱粉、碳酸鈣、滑石粉或二氧化鈦等不溶性粉末均勻分散，著衣於錠劑表面並可予著色，完成著衣之錠劑可使用含蠟之稀薄溶液（如：溶於氯仿）或混合乾粉產生阻光效果",
  "防水材料：防水錠衣可由含{{蟲膠|物質}}或{{酞酸纖維素|物質}}非水性溶劑所形成之溶液，於著糖衣前先著衣處理（應避免過量使用）"
]);
t(2, "錠劑種類", 12, "compressed-tablet", "壓製錠", "壓製錠", [
  "簡介：{{未包衣|性質}}之錠劑，常添加{{稀釋劑、潤滑劑、黏合劑、崩散劑|名詞}}",
  "（{{咀嚼錠|名詞}}可不含崩散劑、一般錠劑可不添加安定劑）"
]);
t(2, "錠劑種類", 13, "enteric-coated", "腸溶衣錠（遲釋錠）（Enteric-coated tablet, ECT）", "腸溶衣錠", [
  "名稱：又稱{{延緩／延遲釋放錠|名詞}}，給藥後延遲一段時間才釋放藥物；特性：可防止藥品被胃酸溶解，延緩藥品釋出（藥典專有名詞 ＝ {{遲釋錠|名詞}}, Delayed-release tablets）",
  "適用：{{易受胃酸破壞、對胃刺激之藥品、需在小腸有高濃度藥品|名詞}}；pKa：{{3-6|數值}}",
  "崩散度試驗（中華藥典第九版）：若具有可溶性外部糖衣，則須先將網架於室溫水中浸泡 {{5 分鐘|數值}}，再進入酸性階段測試；若無糖衣（一般腸溶衣錠），則不須浸水，可直接進入酸性階段測試",
  "第一階段（{{酸性階段|名詞}}）：使用 {{0.1 M 鹽酸|物質}}或人工胃液，於 37±2°C 溫度下測試 {{1 小時|數值}}，不得有崩散、碎裂或軟化等情形",
  "第二階段（{{緩衝階段|名詞}}）：使用 {{pH 6.8 磷酸鹽緩衝液|物質}}或人工腸液，於 37±2°C 溫度下測試，測試時間依藥品個論而定，測試結果應完全崩散（同一般錠劑合格基準）",
  "材料：{{Bee wax|物質}}（蜂蠟）、{{Shellac|物質}}（蟲膠）、Methacrylic acid copolymer（MAAC）、Methylcellulose phthalate（MCP）、Polyvinyl acetate phthalate（PVAP）、Hydroxypropyl methylcellulose phthalate（{{HPMCP|物質}}）",
  "材料：{{Ethylcellulose|物質}}，較常使用於{{非腸溶性膜衣|名詞}}；{{Cellulose acetate phthalate|物質}}（CAP），{{最常使用|性質}}之膜衣（包衣）材料，不溶於水（可能降低錠劑崩散效率）"
]);
t(2, "錠劑種類", 13, "sr-chewable-buccal", "持續釋放錠、咀嚼錠、口頰錠、口腔錠", "SR／咀嚼／口頰", [
  "{{持續釋放錠|名詞}}（Sustained Release Tablets）：又稱{{控制釋放錠、延長釋放錠|名詞}}（Extended release tablets）；延長作用時間，可持續釋出藥品至某一時段",
  "{{咀嚼錠|名詞}}（Chewable tablet）：於口腔咀嚼溶解，可不添加{{崩散劑|名詞}}，大多由{{濕粒法|名詞}}製成",
  "咀嚼錠稀釋劑：山梨醇、{{甘露醇|物質}}（Mannitol，咀嚼錠最常見主要成分，可作為抗凍劑）、{{木醣醇|物質}}（Xylitol，最具甜味、咀嚼時有清涼感）、蔗糖",
  "{{口頰錠|名詞}}：放置口腔頰側，可{{避免首渡代謝|藥動}}",
  "{{口腔錠|名詞}}（Buccal tablet）：放置於口腔之錠劑；崩散度試驗時，應於 {{4 小時|數值}}內崩散"
]);
t(2, "錠劑種類", 14, "lozenge-rdt-sublingual", "口含錠、速溶錠、舌下錠", "口含／速溶／舌下", [
  "{{口含錠|名詞}}（Lozenge tablet）：以{{硬糖果|物質}}為基底，在口腔中緩慢溶離；可產生全身或{{局部|名詞}}作用、適用於易受胃酸降解藥物；於高程度壓錠下完成製備，使其可以緩慢溶解釋出活性成分",
  "{{速溶錠|名詞}}（Rapid dissolve tablet, RDT）：又稱{{口崩錠|名詞}}（Rapidly disintegrating tablet）、立即釋放錠（Instant release tablet）；屬於即時釋放錠，可在大約 {{1 分鐘|數值}}內崩散或溶解，適合{{吞嚥動作困難者|族群}}",
  "速溶錠藥品：最先使用{{冷凍乾燥法 Zydis|名詞}} 技術所製成之藥品如 Claritin Reditabs, Maxalt-MLT, Zofran ODT；添加：壓製法製備速溶錠時，可添加{{發泡劑|名詞}}（Effervescents）增強速溶效果",
  "{{舌下錠|名詞}}（Sublingual tablet）：放置舌下，經口腔黏膜{{迅速吸收|藥動}}，可{{避免首渡代謝|藥動}}（適用於易受胃酸降解藥物）；適用於小分子、低溶解度藥物，可產生全身或局部作用（以全身作用為主）",
  "舌下錠試驗：需進行{{崩散度試驗|名詞}}；藥物：常見舌下錠如{{硝化甘油|藥名}}（NTG）"
]);
t(2, "錠劑種類", 14, "repeat-action", "重複作用錠（Repeat action tablet）", "重複作用錠", [
  "特性：可使藥品維持一定血中濃度、減少給藥次數；適用{{低劑量且吸收排除相對快速|名詞}}之藥物（{{不適用於急症|性質}}）",
  "設計：{{速放藥層 ＋ 控釋膜層 ＋ 核蕊藥錠|名詞}}",
  "材質：常用膜衣包含 {{Cellulose acetate phthalate|物質}}"
]);
t(2, "錠劑種類", 14, "effervescent", "發泡錠（Effervescent tablet）", "發泡錠", [
  "特性：與水接觸後可產生{{二氧化碳|物質}}，加速藥物崩散、增加藥品溶離速率",
  "成分：{{檸檬酸|物質}}（Citric acid），{{19%|數值}}；單獨使用則混合物{{黏度較大，不易造粒|性質}}",
  "成分：{{碳酸氫鈉|物質}}（Sodium bicarbonate），{{53%|數值}}；含量{{最多|性質}}，決定製劑{{酸度|名詞}}",
  "成分：{{酒石酸|物質}}（Tartaric acid），{{28%|數值}}；添加過量會有{{苦澀味|性質}}，且易使顆粒{{失去硬度，變成碎片|性質}}",
  "比例：檸檬酸：碳酸氫鈉：酒石酸 ＝ {{19：53：28|數值}}（約 20：50：30），可記 {{2：5：3|數值}}（簡化後比例因人而異，有些題目寫檸檬酸：酒石酸 ＝ 1：2）",
  "配製：先溶解於水中，經發泡反應釋出藥物，形成均勻溶液後再服用；備註：{{不適合直接吞服|性質}}（未溶解發泡錠可能導致胃中產氣過多，導致腸胃不適、腹脹）"
]);
t(2, "錠劑種類", 15, "osmotic-pump", "滲透壓控釋錠（Osmotic pump tablet）", "滲透壓控釋錠", [
  "優點：食物、胃腸酸鹼值、離子強度、胃腸蠕動等因素{{較不會|性質}}對藥物釋放造成影響",
  "釋放：{{滲透表面積、半透膜厚度、雷射孔徑大小|名詞}}等因素會影響藥物釋放速率"
]);
t(2, "錠劑種類", 15, "sugar-coated", "糖衣錠（Sugar coated tablet）", "糖衣錠", [
  "特性：掩蓋藥品不良氣味、防止藥品分解，糖衣可能增加藥品重量約 {{50-100%|數值}}",
  "包覆步驟：1. {{防水層|名詞}}（固封防水，Sealing and Waterproofing）：防止水份滲入，常用材料：{{蟲膠、CAP、PVAP|物質}}",
  "2. {{底衣層／初包衣|名詞}}（Subcoating）：體積增加約 50~100%；3. {{平滑層／打平滑|名詞}}（Smoothing）",
  "4. {{著色|名詞}}（Coloring）：可加入色素、TiO₂ 等；5. {{磨光／打亮|名詞}}（Polishing）：常用材料：{{蜂蠟（黃蠟）|物質}}",
  "缺點：{{施工時間長、需防水|性質}}，可能{{阻礙有效成分釋出|副作用}}、最終成品{{體積大增|性質}}"
]);
t(2, "錠劑種類", 15, "film-coated", "膜衣錠", "膜衣錠", [
  "簡介：將{{有機溶媒|物質}}噴灑於錠劑表面",
  "水溶性物質：{{HPMC|物質}}（Hydroxypropyl Methylcellulose）、甲基纖維素、HPC（Hydroxypropyl cellulose）、聚乙二醇混合物、PVP（Polyvinyl pyrrolidone）",
  "非水溶性物質：{{CAP|物質}}（Cellulose acetate phthalate）",
  "外觀：溶劑蒸發後，留有一層薄膜黏附於錠劑表面（仍保有{{原始外型、溝線與識別符號|名詞}}等）",
  "優點：操作簡單、安定、{{不需固封步驟|性質}}；缺點：{{爆炸性、環境汙染|副作用}}（皆因含有機溶媒）",
  "其他：Rapidly disintegrating tablet, Effervescent tablet, Chewable tablet 以及 Molded tablet 中，硬度相對較大者為 {{Effervescent tablet 與 Chewable tablet|名詞}}"
]);
t(2, "製錠方法", 16, "wet-granulation", "濕式法／濕式顆粒法／濕式造粒法／濕粒法（Wet Granulation）", "濕粒法", [
  "使用顆粒法製造可{{促進粉流動性、提高錠劑壓縮性與重量均一度|名詞}}",
  "簡介：將主藥研細後，加入稀釋劑、黏合劑等添加物形成濕團塊後，經過造粒、整粒、潤滑、打錠等過程所製成之錠劑",
  "造粒：使用 {{6、8 號|數值}}篩網（製成顆粒）（可提高藥品黏合性、流動性、密度）",
  "整粒：使用 {{12-20 號|數值}}篩網（去除大顆粒）（造粒、整粒粉末約佔全部重量之 {{10-20%|數值}}）",
  "步驟：秤重 → 混合、溼塊、過篩 → 造粒 → 乾燥 → 整粒 → 潤滑 → 打錠（打錠前再潤滑（{{潤滑為打錠前一個步驟|名詞}}））",
  "相關設備：{{流體床造粒機|名詞}}（依濕粒法所改良）"
]);
t(2, "製錠方法", 16, "fluid-bed", "流體床造粒機", "流體床", [
  "優點：流動性好、效率高、時間短，可{{一次完成混合、造粒、乾燥|名詞}}等過程",
  "相關性：{{Barrier film|名詞}} 與{{膜衣|名詞}}有關；{{Enteric-release|名詞}} 與{{腸溶|名詞}}有關；{{Taste masking|名詞}} 與{{味覺|名詞}}有關",
  "{{頂噴|名詞}}（Top-spray）：自上往下噴（噴嘴向下噴，熱空氣由下方吹起藥品）；適用於 {{Barrier film、Enteric-release、Taste masking|名詞}}；包衣材料適合使用{{熱熔材料|物質}}（Hot melts）、乳膠（Latexes）、水溶液（Aqueous solutions）",
  "{{底噴|名詞}}（Bottom-spray）：噴嘴與熱空氣由下往上噴；適用於 {{Sustained release、Enteric-release|名詞}}",
  "{{正切噴／側噴|名詞}}（Tangential-spray）：噴嘴自機器側邊噴灑；適用於 Sustained release、Enteric-release"
]);
t(2, "製錠方法", 16, "dry-granulation", "乾式法／乾式顆粒法／乾式造粒法／乾粒法（Dry Granulation/Slugging）", "乾粒法", [
  "別名：又稱{{重壓法、大錠法、兩次壓錠法|名詞}}，將成分混和均勻後壓製成錠",
  "步驟：混合 → 壓錠 → 製粒 → 潤滑 → 壓錠（乾粒法需{{壓錠兩次|名詞}}）",
  "特性：適用於{{不耐熱或對水氣敏感|性質}}之物質（如 {{Aspirin|藥名}}）",
  "缺點：{{硬度較高、密度較大、藥物溶離釋出量較低|性質}}"
]);
t(2, "製錠方法", 17, "direct-compression", "直接壓錠法、直壓法（Direct compression）", "直壓法", [
  "簡介：將原料藥與具有良好{{流動性及可壓性|性質}}之賦形劑混合後，直接壓製成錠，製程可省略濕式或乾式製粒步驟，可減少設備、時間以及能源消耗；若成分之間粒徑、密度或流動性差異較大，製程中可能發生{{粉體分離|名詞}}，進而影響錠劑重量均一性或含量均一度",
  "稀釋劑：乳糖、{{乾燥噴霧乳糖|物質}}（Spray-dried lactose）、磷酸二鈣（dicalcium phosphate）；{{微晶纖維素|物質}}（Microcrystalline cellulose, MCC）（商品名 {{Avicel|物質}}）",
  "稀釋劑：α-乳糖-水合物微晶（Microcrystals of alpha-monohydrate lactose）；蔗糖-轉化糖-玉米澱粉混合物（Sucrose-invert sugar-corn starch mixtures）、麥芽糖結晶（Crystalline maltose）",
  "崩散劑：澱粉、乳糖（Lactose）、玉米澱粉（Maize starch）、HPMC（羥丙基甲基纖維素）",
  "潤滑劑：{{硬脂酸鎂、滑石粉|物質}}（Talc）；助滑劑：{{膠狀二氧化矽|物質}}（Silicon dioxide）",
  "備註：若壓錠過程{{參入空氣|名詞}}，錠劑容易發生{{分層、頂裂、層裂|名詞}}，可藉由{{降低壓錠壓力與速度|名詞}}避免發生"
]);
t(2, "製錠方法", 17, "tablet-defects", "分層（Laminating）、頂裂（Capping）、層裂（Splitting）", "錠劑缺陷", [
  "{{分層|名詞}}（Laminating）：外觀：水平方向分成兩層或多層；裂痕：{{水平方向|名詞}}；原因：1. 粉體內空氣未充分排出，壓縮不均 2. 空氣未完全排出 3. {{過量潤滑劑|物質}}降低粒子間結合力",
  "分層解決：1. 改善粉體流動性、可壓縮性與均勻度 2. 降低壓錠壓力與速度 3. {{避免過量潤滑劑|名詞}}",
  "{{頂裂|名詞}}（Capping）：外觀：錠劑上／下表面剝落或破裂；裂痕：水平方向（{{頂部或底部|部位}}）；原因：1. 壓錠過程中粉體內部空氣未排除 2. 粉體粒子間黏合力不足，壓力釋放時導致錠劑破裂 3. {{沖模未完整清潔|名詞}}，導致粉末分佈不均",
  "頂裂解決：1. 降低壓錠壓力與速度，使空氣充分排出 2. {{添加黏合劑|名詞}}提高黏合力 3. 確保沖模清潔",
  "{{層裂|名詞}}（Splitting）：外觀：垂直方向出現裂痕；裂痕：{{垂直方向|名詞}}；原因：1. 壓縮力過大或壓縮後彈性回復，造成內部應力與垂直裂痕 2. 粒子間結合不均、黏合劑不足或粉體混合不均勻 3. 錠劑內{{水分分佈不均|名詞}}",
  "層裂解決：1. 調整壓力避免過度壓縮 2. 調整黏合劑種類或用量，改善顆粒均勻度與粒子間結合力 3. {{控制錠劑含水量|名詞}}"
]);
t(2, "製錠方法", 18, "tablet-press", "壓錠機", "壓錠機", [
  "{{上沖模|名詞}}（Upper punches），於壓縮階段向下進入模孔，使模孔內粉體受壓縮而形成錠劑，壓縮程度會影響{{錠劑硬度、厚度、密度及孔隙率|名詞}}",
  "{{下沖模|名詞}}（Lower punches），於填充階段下降或調整至適當位置，以形成模孔填充空間；其填充位置或深度會影響模孔內粉體填充量，因此為控制{{錠劑重量|名詞}}之重要因素，壓縮時，下沖模亦作為粉體承托端；成錠後可上升協助推出錠劑",
  "壓錠順序：{{填充階段|名詞}}：下沖模調整至適當位置形成模孔空間，粉體進入模孔；{{壓縮階段|名詞}}：上、下沖模相對接近，使粉體受壓形成錠劑；{{出錠階段|名詞}}：下沖模上升，將成錠推出模孔",
  "導致重量差異：{{流動性不良、顆粒大小不均、下沖模下降程度不一|名詞}}",
  "中華藥典（歷年曾考過內容）：理想細粉量約 {{10-20%|數值}}；理想藥品量 {{20-25%|數值}}（> 25-30% 可能不易壓製成型）",
  "硬度不足：可藉由{{提高壓錠力量|名詞}}改善"
]);
t(2, "添加物", 19, "diluents", "稀釋劑（Diluents）", "稀釋劑", [
  "別名：又稱{{填充劑|名詞}}（Fillers）；功用：增加藥品重量與體積，多為{{惰性物質|性質}}",
  "{{乳糖|物質}}，具有良好溶解度與相容性，為{{最常用|性質}}之稀釋劑",
  "{{澱粉|物質}}，適合利用{{溫水|名詞}}溶解（熱水被劃掉）",
  "{{微晶纖維素|物質}}（MCC），良好{{相容性、均一度、溶解度|性質}}、適用於{{直接壓錠|名詞}}",
  "{{固醇類錠劑|名詞}}，可用{{硫酸鈣|物質}}（Calcium sulfate）作為稀釋劑",
  "{{咀嚼錠|名詞}}，添加{{山梨醇、甘露醇、木醣醇、蔗糖|物質}}作為稀釋劑"
]);
t(2, "添加物", 19, "lubricants", "潤滑劑：Lubricants、Anti-adherents、Glidants", "潤滑劑", [
  "功用：降低藥品摩擦以及對機器之黏附；用量：大多 < {{1%|數值}}（{{滑石粉|物質}}最多可添加至 {{5%|數值}}）",
  "{{Lubricants|名詞}}（潤滑劑）：降低顆粒與容器、衝模之摩擦力；物質：{{硬脂酸鎂|物質}}（Magnesium stearate，用量 ≤ 1%，否則易發生{{雨衣效應|名詞}}）、滑石粉、Sodium lauryl sulfate；［註］雨衣效應 ＝ {{延遲藥物崩散、溶離時間|副作用}}",
  "{{Anti-adherents|名詞}}（抗黏著劑）：減少顆粒黏著，降低顆粒凝集；物質：硬脂酸鎂、滑石粉、玉米澱粉、Sodium lauryl sulfate（SLS）、Fumed silicon dioxide（Colloidal silica、膠狀二氧化矽、SiO₂）",
  "{{Glidants|名詞}}（助滑劑／滑動劑）：減少顆粒之間摩擦力，增加顆粒{{流動性|性質}}；物質：硬脂酸鎂、滑石粉、澱粉、SiO₂",
  "備註：{{SiO₂|物質}} 特性：{{吸水量大、黏度易受 pH 值影響|性質}}、pH {{7.5|數值}} 環境下較安定",
  "比較：硬脂酸鎂、滑石粉：潤滑劑 ✓、抗黏著劑 ✓、助滑劑 ✓；{{SLS|物質}}：潤滑劑 ✓、抗黏著劑 ✓；{{SiO₂|物質}}：抗黏著劑 ✓、助滑劑 ✓",
  "功用：潤滑劑 ＝ {{降低機器摩擦力|名詞}}；抗黏著劑 ＝ {{防止顆粒附著|名詞}}；助滑劑 ＝ {{改善顆粒流動性|名詞}}"
]);
t(2, "添加物", 20, "binders", "黏合劑（Binders）", "黏合劑", [
  "功用：提供黏合力，使顆粒容易流動",
  "物質：{{阿拉伯膠|物質}}（Acacia）、MCC、MC（甲基纖維素）、普維酮碘（Povidone）（對水敏感可改用 {{HPMC, HPC, EC|物質}}）",
  "{{HPMC|物質}}（Hydroxypropyl methylcellulose，羥丙基甲基纖維素）：{{較不影響口服吸收作用|性質}}（對藥物口服吸收速率影響較小）；易溶於{{冷水|物質}}，在熱水中較易分散",
  "{{Ethylcellulose|物質}}（EC，乙基纖維素）：{{不溶於水|性質}}，容易阻礙藥物釋出；Colorcon 公司出產之 {{Surelease|物質}} 含 Ethylcellulose",
  "{{PVP|物質}}（Polyvinylpyrrolidone，聚乙烯吡咯烷酮）：{{易溶於水|性質}}；{{HPC|物質}}（Hydroxypropyl cellulose，羥丙基纖維素）"
]);
t(2, "添加物", 20, "disintegrants", "崩散劑（Disintegrants）", "崩散劑", [
  "功用：促進藥品崩散（可部分增加溶離效果）",
  "物質：澱粉、{{預糊化澱粉|物質}}（Pregelatinized starch）、玉米澱粉、海藻酸、MCC、PVP",
  "{{超級崩散劑|名詞}}：{{Sodium starch glycolate, Croscarmellose|物質}}，透過{{吸水膨脹|名詞}}產生快速崩散效果；{{Crospovidone|物質}}，透過{{毛細作用|名詞}}產生快速崩散效果",
  "其他：可添加{{發泡劑|名詞}}（Effervescents）增強速溶效果；{{乳糖|物質}}（Lactose）可部分增加難溶性藥品之溶離速率"
]);
t(2, "微粒包衣", 20, "microencapsulation", "微粒包衣技術、微膠囊化（Microencapsulation）", "微膠囊化", [
  "簡介：將藥品（{{芯材|名詞}}）用薄膜包覆，可增加藥品穩定性，防止內容物產生交互作用",
  "材料：{{明膠|物質}}（最常用）、MC、CAP、EC、HPC、HPMC、PVA（Polyvinyl alcohol）"
]);
t(2, "微粒包衣", 20, "ncr", "NCR（National Cash Register）技術", "NCR 技術", [
  "原理：在聚合物中加入物質，使其產生相的分離或{{凝聚作用|名詞}}（Coacervation）",
  "組成：液相、芯材料相（聚合物）、薄衣材料相（常用{{明膠 ＋ 甲醛|物質}}）",
  "［註］甲醛在{{低溫|名詞}}環境下易產生{{聚合反應|反應}}，形成{{白色|顏色}}結晶",
  "［註］{{加溫|名詞}}可使薄衣硬化（形成微膠囊）"
]);
t(2, "錠劑試驗", 21, "hydrophilic-matrix", "親水間質系統", "親水間質", [
  "原理：遇水後形成{{凝膠|名詞}}，產生控釋能力",
  "材料：{{HPMC|物質}}（最理想、最常用），具有親水性",
  "製備：常用於製備{{延長釋放錠|名詞}}（或膠囊），可做成單層、雙層及三層之控釋劑型",
  "其他：製備時通常{{不需|性質}}額外加入{{塑化劑|物質}}（Plasticizer）"
]);
t(2, "錠劑試驗", 21, "friability", "脆度試驗（Friability Test）", "脆度試驗", [
  "簡介：測試{{無加衣錠劑|名詞}}受到機械應力後，對{{碎屑和表面磨耗|名詞}}之抗性，適用於大部分壓製錠劑；此試驗會將錠劑放入特定裝置，進行旋轉與跌落等試驗，並模擬運輸和處理過程中所產生之碰撞與摩擦，再測量錠劑重量損失，以評估其脆度",
  "目的：確保錠劑在運輸、包裝以及使用過程中不易碎裂，保持完整性與有效性",
  "內容：重量 {{650 mg|數值}} 或以下者，取若干錠劑使其總重量接近 {{6.5 g|數值}}",
  "試驗前除去錠劑表面粉塵，精確秤重後放入脆度計（圓筒裝置）轉動 {{100|數值}} 次",
  "一般僅須進行 {{1|數值}} 次試驗，若試驗後檢品出現明顯裂紋、開裂或碎片，應判定{{不合格|名詞}}；若第一次試驗無法判定，或重量損失率超過限定值，則應{{再試驗 2 次|名詞}}，並以 3 次試驗之{{平均重量減少率|名詞}}判定，大多數藥品平均重量減少率不得超過 {{1%|數值}}",
  "（備註）{{發泡錠與咀嚼錠|名詞}}之脆度試驗{{可有不同規格|性質}}"
]);
t(2, "錠劑試驗", 21, "disintegration-types", "崩散度試驗：種類與釋放名詞", "崩散度種類", [
  "種類：大多數錠劑需進行崩散度試驗，但{{咀嚼錠、延長釋放錠、持續釋放錠|名詞}}不須進行（{{延遲、延緩釋放錠要做|性質}}崩散度試驗）",
  "{{延長釋放|名詞}}（Extended-release），表示刻意{{延長藥品釋放時間|名詞}}之劑型",
  "{{持續釋放|名詞}}（Sustained-release），通常可視為延長釋放劑型之其中一種表現方式",
  "{{延遲／延緩釋放|名詞}}（Delayed-release），屬於{{修飾釋放|名詞}}（Modified-release）劑型之一，給藥後會{{延遲|性質}}一段時間，才將藥品活性成分自製劑中釋出（第八版稱為「延緩性釋出（Delayed-release）」，第九版正名為「{{遲釋|名詞}}」，為刻意配製，使給藥後延遲一段時間才釋放藥物之劑型）"
]);

/* ===== 第 3 章 軟膏劑（拍攝第 22～35 頁）===== */
ch(3, "軟膏劑", "22～35");
t(3, "軟膏劑", 22, "ointment-basics", "軟膏劑：簡介、儲存、基劑", "軟膏概論", [
  "簡介：一種或多種藥品 ＋ 基劑形成具有適當稠度之{{膏狀半固體外用製劑|名詞}}，常見半固體外用製劑如{{糊劑、膠劑、軟膏、乳霜|名詞}}",
  "儲存：{{30°C|數值}} 以下之{{密蓋容器|名詞}}；［比較］{{眼用軟膏|名詞}}保存於 {{15°C|數值}} 以下之{{滅菌緊密容器|名詞}}",
  "基劑：構成主要體積與性質之載體，可使藥物溶解、懸浮或均勻分散，並影響藥物釋放、皮膚滲透、滋潤性及可洗除性"
]);
t(3, "軟膏劑", 22, "ointment-bases", "軟膏分類：軟膏基劑", "軟膏基劑分類", [
  "{{烴類基劑|名詞}} → {{軟石蠟、軟膏|物質}}",
  "{{吸收性基劑（無水）|名詞}} → {{親水軟石蠟、無水羊毛脂|物質}}",
  "{{吸收性基劑（w/o 型乳劑）|名詞}} → {{冷霜、含水羊毛脂、Eucerin|物質}}",
  "{{水和性基劑（o/w 型乳劑）|名詞}} → {{親水軟膏、消散乳霜|物質}}",
  "{{水溶性基劑|名詞}} → {{聚乙二醇（PEG）|物質}}"
]);
t(3, "軟膏基劑", 22, "hydrocarbon-base", "烴類基劑（Hydrocarbons, Oleaginous）", "烴類基劑", [
  "特性：屬於{{油溶性|性質}}軟膏基劑，{{不含水、不吸水、不溶於水、不易水洗|性質}}",
  "功用：{{潤膚|藥效}}（可增加皮膚接觸時間，但吸收量少）",
  "{{軟石蠟|物質}}（Petrolatum）：{{黃軟石蠟|物質}}，俗稱{{凡士林|物質}}（Vaseline）；{{白軟石蠟|物質}}，黃軟石蠟{{脫色|反應}}而得",
  "{{軟膏|物質}}（Ointment）：{{黃軟膏|物質}}（Yellow ointment）、{{白軟膏|物質}}（White ointment）"
]);
t(3, "軟膏基劑", 22, "absorption-base", "吸收性基劑（Absorption）：無水型、含水型", "吸收性基劑", [
  "{{無水型|名詞}}：特性：{{不含水|性質}}（含親水成分）、{{會吸水|性質}}、不溶於水、不易水洗；可與水性藥物進行研合",
  "無水型物質：{{親水軟石蠟|物質}}（Hydrophilic petrolatum）、{{無水羊毛脂|物質}}（Anhydrous lanolin）、Aquaphor、Aquabase",
  "{{含水型|名詞}}（W/O 型乳劑）：特性：{{含水、會吸水|性質}}、不溶於水、不易水洗（比起無水型吸收性基劑，可與{{較多量|性質}}水溶液研合）",
  "含水型物質：{{冷霜|物質}}（Cold cream）、{{含水羊毛脂|物質}}（Hydrous lanolin，可增加油溶性軟膏基劑吸水能力）、{{Eucerin|物質}}（優色林）"
]);
t(3, "軟膏基劑", 23, "ow-base", "水和性基劑（O/W 型乳劑）", "水和性基劑", [
  "特性：{{含水、會吸水、水可洗除|性質}}、不溶於水",
  "物質：{{親水軟膏|物質}}（Hydrophilic ointment）、{{消散乳霜|物質}}（Vanishing cream）、{{乳霜|物質}}（Cream），也可供{{陰道投藥|給藥途徑}}用"
]);
t(3, "軟膏基劑", 23, "water-soluble-base", "水溶性基劑（Water soluble）", "水溶性基劑", [
  "組成：水溶性物質",
  "特性：可溶於水、會吸水、水可洗除（無油膩性）、{{無水|性質}}（通常不含水）；水溶性基劑不含軟石蠟、羊毛脂等水不溶性成分，又稱{{無油性軟膏基劑|名詞}}",
  "備註：含有水溶性物質，可能對{{發炎組織|名詞}}具有刺激性",
  "物質：{{聚乙二醇|物質}}（Polyethylene glycol, PEG）（商品名 {{Carbowax|物質}}）",
  "製備 PEG 軟膏：若需加入含水溶液時，可加入{{硬脂醇|物質}}（Stearyl alcohol，又稱十八醇）作為{{硬化劑|名詞}}（減少軟化現象）；可用{{熔合法|名詞}}製備（與 PEG 栓劑相同）"
]);
t(3, "軟膏基劑", 23, "ointment-base-summary", "軟膏基劑總整理", "基劑總整理", [
  "{{烴類基劑|名詞}}：吸水 ✗、含水 ✗、水洗除 ✗、水溶 ✗；物質：{{軟石蠟、單軟膏|物質}}",
  "{{吸收性基劑（無水）|名詞}}：{{吸水 ✓|性質}}；物質：親水軟石蠟、無水羊毛脂、Aquaphor、Aquabase",
  "{{吸收性基劑（W/O 乳劑）|名詞}}：吸水 ✓、{{含水 ✓|性質}}；物質：冷霜、含水羊毛脂、Eucerin",
  "{{水和性基劑（O/W 乳劑）|名詞}}：吸水 ✓、含水 ✓、{{水洗除 ✓|性質}}；物質：乳霜、親水軟膏、消散乳霜",
  "{{水溶性基劑|名詞}}：吸水 ✓、水洗除 ✓、{{水溶 ✓|性質}}；物質：{{聚乙二醇|物質}}"
]);
t(3, "軟膏基劑 II（依照物理化學性質分類）", 24, "hydrocarbon-materials", "烴類（Hydrocarbon）：軟石蠟、軟膏、微晶蠟、Plastibase、液體石蠟", "烴類物質", [
  "烴類（Hydrocarbon），具有{{軟化、保護皮膚以及防止水分流失|藥效}}作用",
  "{{軟石蠟|物質}}（Petrolatum）：黃軟石蠟，俗稱凡士林（Vaseline）；白軟石蠟，黃軟石蠟脫色而得；{{軟膏|物質}}（Ointment）：黃軟膏、白軟膏",
  "{{微（結）晶蠟|物質}}（Microcrystalline wax）：從石油提煉之柔軟、高延展性固體，與普通石蠟不同，微晶蠟之結晶細小，{{彈性佳，黏性高|性質}}，熔點約 {{65-90°C|數值}}，可與多種油類、蠟質互溶，具有極佳保油性與成膜性，常作為化妝品增稠劑、防鏽劑、工業用上光劑等",
  "{{Plastibase|物質}}（Jelene）：屬於{{人工合成|性質}}之軟石蠟，在 {{-15~60°C|數值}} 可維持稠度；組成：{{聚乙烯 5% ＋ 礦物油 95%|物質}}；功用：可作為{{口腔保護劑|名詞}}基劑成分，用於口腔黏膜形成保護膜，保護發炎或磨擦引起之潰瘍部位",
  "{{液體石蠟|物質}}（Liquid paraffin）：又稱{{礦物油|物質}}（Mineral oil），可作為{{研合劑|名詞}}，與藥物粉末研合均勻"
]);
t(3, "軟膏基劑 II（依照物理化學性質分類）", 24, "levigating-agent", "研合劑（Levigating agent）", "研合劑", [
  "功用：可潤濕、分散藥物粉末，促進藥品均勻併入基劑中，也可降低成品之{{砂礫感或粗糙感|性質}}",
  "調配：大多使用{{不鏽鋼刀|名詞}}，但{{水楊酸、鞣酸|物質}}（Tannic acid）、汞、碘需使用{{硬橡膠刀|名詞}}",
  "備註：若欲將藥物緩慢溶解於體液中，可使用{{鞣酸|物質}}（Tannic acid）或{{鞣酸酸鹽|物質}}（Tannate），此兩種物質與藥物結合後可形成緩慢溶解之複合物，依據外在體液之酸鹼值而緩慢釋出，可以此方式達到{{長效釋放|名詞}}目的或製備長效劑型",
  "物質與研合劑：{{樟腦|物質}} → {{乙醇|物質}}；{{碘結晶|物質}} → {{乙醚|物質}}；{{硫磺軟膏|物質}} → {{液體石蠟（礦物油）|物質}}",
  "物質與研合劑：{{祕魯香膠|物質}} → {{蓖麻油|物質}}；{{氧化鋅軟膏|物質}} → 液體石蠟（礦物油）"
]);
t(3, "軟膏基劑 II（依照物理化學性質分類）", 25, "alcohols", "醇類：單元醇、多元醇、環狀醇", "醇類", [
  "{{單元醇|名詞}}：組成：含 {{12~18|數值}} 個碳之脂肪醇；物質：{{硬脂醇|物質}}（Stearyl alcohol）、{{鯨蠟醇|物質}}（Cetyl alcohol）；功用：{{軟膏硬化劑或乳劑安定劑|名詞}}",
  "{{多元醇|名詞}}：組成：含多個羥基之脂肪醇；物質：乙二醇、丙二醇、丙三醇（Glycerol，甘油）、Sorbitol（山梨醇）、PEG（聚乙二醇）；功用：含水型軟膏基劑（如 W/O、O/W 型乳劑）之{{保濕劑|名詞}}、水溶性基劑（如 PEG）",
  "{{環狀醇|名詞}}：組成：結構式為環狀之醇類；物質：{{膽固醇|物質}}（Cholesterol）；功用：可作為吸收性軟膏基劑中之{{乳化輔助成分|名詞}}，增加基劑吸水能力"
]);
t(3, "軟膏基劑 II（依照物理化學性質分類）", 25, "stearic-acid-soaps", "酸類：硬脂酸與各種肥皂", "硬脂酸肥皂", [
  "硬脂酸 ＋ {{氫氧化鉀|物質}}（Potassium hydroxide）＝ {{鉀肥皂|物質}}：具有{{珍珠光澤|性質}}，屬於陰離子型界面活性劑（弱鹼性）",
  "硬脂酸 ＋ {{硼酸鈉|物質}}（Sodium borate）＝ {{鈉肥皂|物質}}：外觀呈現{{白色、具有顆粒感|性質}}",
  "硬脂酸 ＋ {{三乙醇胺|物質}}（Triethanolamine）＝ {{胺肥皂|物質}}：{{質地最佳|性質}}、具有珍珠光澤，屬於陰離子型界面活性劑（弱鹼性）",
  "硬脂酸 ＋ 鈉／鉀／銨鹽（{{一價金屬|名詞}}）：可形成 {{O/W|名詞}} 型乳劑（增加軟膏穿透能力）",
  "硬脂酸 ＋ 鈣／鎂鹽（{{二價金屬|名詞}}）：可形成 {{W/O|名詞}} 型乳劑"
], ["講義此表拍攝歪斜，右欄說明與左欄的對應依版面判讀"]);
t(3, "軟膏基劑 II（依照物理化學性質分類）", 25, "vanishing-cream", "相關製劑：消散乳霜", "消散乳霜", [
  "乳化劑：脂肪酸，如{{硬脂酸|物質}}（Stearic acid, {{10-25%|數值}}）；{{氫氧化鉀|物質}}（Potassium hydroxide）；上述兩者可形成{{鉀肥皂|物質}}",
  "保濕劑：醇類物質，如{{丙二醇|物質}}（Propylene glycol）",
  "潤膚劑、增稠劑：可添加{{鯨蠟醇|物質}}（Cetyl alcohol）← 也可作為{{油相基底|名詞}}",
  "活性藥物：醫療用途之乳霜含特定活性藥物成分（如 {{Tacrolimus|藥名}}）；另含防腐劑、純淨水"
]);
t(3, "軟膏基劑 II（依照物理化學性質分類）", 26, "esters", "酯類：單元醇-酯、環狀醇-酯、甘油單硬脂酸酯、蓖麻油", "酯類", [
  "{{單元醇-酯|名詞}}：特性：多為{{高熔點蠟類|性質}}；物質：{{蜂蠟（黃蠟）、巴西棕櫚蠟|物質}}；功用：提高軟膏劑硬度（{{硬化劑|名詞}}）",
  "{{環狀醇-酯|名詞}}：特性：多為{{膽固醇類|物質}}物質；可作為界面活性劑、增加軟石蠟含水數、增加 Vaseline 吸水能力",
  "{{甘油單硬脂酸酯|物質}}（Glyceryl monostearate）：與硬脂酸鈉併用，可產生{{自身乳化作用|名詞}}（Self-emulsifying）（加水後不需額外添加乳化劑，即可自動形成穩定 {{O/W|名詞}} 乳劑）",
  "{{蓖麻油|物質}}（Castor oil）：可溶解於 {{95% 乙醇|物質}}；九號碳為{{雙鍵|結構}}（△C9）、十二號碳接{{羥基|結構}}（C12-OH）"
]);
t(3, "軟膏基劑 II（依照物理化學性質分類）", 26, "span-tween", "多元醇-酯：Span、Tween、Myrjs、Brijs", "Span／Tween", [
  "{{Span|物質}}：無水山梨醇（Sorbitan）與脂肪酸所形成之{{酯類|名詞}}（Ester）；可形成 {{W/O|名詞}} 型乳劑；HLB 值 {{3-6|數值}}；界面活性劑中，{{Arlacel|物質}} 性質與 Span 相近",
  "Span20 ＝ Sorbitan {{monolaurate|物質}}（山梨醇酐月桂酸酯）；Span40 ＝ Sorbitan monopalmitate（棕櫚酸酯）；Span60 ＝ Sorbitan monostearate（硬脂酸酯）；Span80 ＝ Sorbitan {{monooleate|物質}}（山梨醇單油酸酯）",
  "{{Tween|物質}}：無水山梨醇（Sorbitan）＋ 脂肪酸 ＋ {{20|數值}} 個 Polyethylene oxide 所形成之酯類；可形成 {{O/W|名詞}} 乳劑；HLB 值 {{8-18|數值}}；併用 Span 效果更佳",
  "Tween 比 Span 多了 20 個{{醚氧基|結構}}（Polyethylene oxide）（醚氧基之水合作用為{{放熱反應|反應}}，增加溫度，溶解度{{下降|性質}}）",
  "{{Myrjs|物質}}：脂肪{{酸|名詞}} ＋ 20 個 Ethylene oxide 所形成之聚氧乙烯脂肪酸{{酯|名詞}}（Ester）；可形成 O/W 乳劑；對酸鹼{{不安定|性質}}",
  "{{Brijs|物質}}：脂肪{{醇|名詞}} ＋ 20 個 Ethylene oxide 所形成之聚氧乙烯脂肪醇{{醚|名詞}}（Ether）；屬於{{非離子型|名詞}}界面活性劑；對酸鹼{{安定|性質}}"
]);
t(3, "軟膏製劑", 27, "ointment-products-1", "軟膏製劑（一）：白軟膏、水楊酸、鞣酸、硫磺、氧化鋅、Veegum", "軟膏製劑一", [
  "{{白軟膏|物質}}（單軟膏）：油溶性軟膏基劑；成分：{{5% 白蠟 ＋ 95% 白軟石蠟|物質}}",
  "{{水楊酸軟膏|物質}}：{{不可使用金屬容器|性質}}；成分：{{2% 水楊酸 ＋ 98% 白軟膏|物質}}",
  "{{鞣酸軟膏|物質}}（Tannic Ointment）：{{不可使用金屬容器|性質}}；成分：白軟膏、鞣酸、{{甘油|物質}}（助溶劑）、{{無水亞硫酸鈉|物質}}（抗氧化劑）",
  "{{硫磺軟膏|物質}}：外用{{殺菌劑|藥效}}；成分：硫 ＋ 液體石蠟（研合劑）",
  "{{氧化鋅軟膏|物質}}：外用{{收斂劑|藥效}}；成分：氧化鋅 ＋ 液體石蠟（研合劑）",
  "{{Veegum|物質}}（矽酸鎂鋁）軟膏：屬於{{矽化合物|名詞}}；具有{{搖變性|性質}}；成分：矽酸鎂鋁"
]);
t(3, "軟膏製劑", 27, "ointment-products-2", "軟膏製劑（二）：Aquabase、親水軟石蠟、羊毛脂、冷霜、Silicon 類", "軟膏製劑二", [
  "{{Aquabase 軟膏|物質}}：吸收性軟膏基劑（無水）；成分：白軟石蠟、{{棉子油|物質}}、膽固醇",
  "{{親水軟石蠟|物質}}：吸收性軟膏基劑（無水）；成分：白軟石蠟、白臘、{{膽固醇、硬脂醇|物質}}",
  "{{無水羊毛脂|物質}}（Woolfat）（Anhydrous Lanolin）：吸收性軟膏基劑（無水）；含水量需 ≤ {{0.25%|數值}}；吸水可形成 {{W/O|名詞}} 型乳劑；成分：羊毛脂",
  "{{含水羊毛脂|物質}}：吸收性軟膏基劑（W/O 型）；含水量約 {{25-30%|數值}}；成分：羊毛脂、蒸餾水",
  "{{冷霜|物質}}：吸收性軟膏基劑（W/O 型）；功用：{{潤膚劑|藥效}}（有清涼感）；成分：{{鯨蠟、硼酸鈉|物質}}、蒸餾水、白軟石蠟、液體石蠟",
  "{{Silicon 類軟膏基劑|名詞}}：{{Bentonite|物質}}（皂土）、{{Hectorite|物質}}（水輝石）、{{Veegum|物質}}（矽酸鎂鋁）",
  "{{Ciprofloxacin ophthalmic|藥名}} 軟膏：一般檢查包括{{無菌試驗、最低內容量試驗、金屬粒子檢查|名詞}}"
]);
