  "{{吸溼劑|名詞}}：{{DMSO|物質}}（Dimethyl sulfoxide）、DMF（Dimethyl formamide）；{{界面活性劑|名詞}}：SLS（Sodium lauryl sulfate）",
  "{{非極性溶媒|名詞}}：丙酮（Acetone）、石油醚（Petroleum ether）、氯仿（Chloroform）",
  "{{化學吸收促進劑|名詞}}：{{Azone|物質}}（月桂氮酮、Laurocapram）；其他：{{超音波|名詞}}（Ultrasound）、{{離子導入法|名詞}}（Iontophoresis）",
