t(3, "軟膏製法", 33, "ointment-methods", "軟膏製法：研調法、研合法、熔合法、混合法、化學反應法", "軟膏製法", [
  "{{研調法|名詞}}：利用{{研缽與研棒|名詞}}，將藥物與基劑混合均勻",
  "{{研合法|名詞}}：使用軟膏板與金屬軟膏刀反覆研壓、切拌，逐量加入其餘基劑並混合均勻，但{{水楊酸、鞣酸、汞、碘|物質}}可能與金屬反應，應改用{{硬橡膠刀|名詞}}",
  "{{熔合法|名詞}}：透過{{加熱|名詞}}將製劑所需成分熔化，混合均勻後，冷卻或凝固成最終製劑；常用於固體或半固體劑型，如栓劑、軟膏劑、乳劑、蠟類，按照熔點高低依序加入（由{{高熔點 → 低熔點|名詞}}）（如：氧化鋅軟膏）",
  "熔合法缺點：不適用於{{對熱敏感|性質}}藥物（可能因高溫而降解）；加熱過度可能導致分解基質（如{{可可脂產生多晶型變化|名詞}}）",
  "{{混合法|名詞}}（練合法）：常用於製備軟膏劑，將藥物或其他活性成分與基劑在{{不加熱|性質}}之情況下均勻混合，適用對熱敏藥物或需分散於基劑之成分；優點：{{不需加熱|性質}}、均勻分散、適用於油溶性與水溶性基劑",
  "{{化學反應法|名詞}}：在製備過程中，成分之間發生化學反應，藉此產生有效成分或形成特殊基劑，讓藥物具有更佳活性、穩定性或滲透性"
]);
