t(5, "栓劑種類", 44, "cocoa-suppository", "可可脂栓劑", "可可脂栓劑", [
  "{{捏合法|名詞}}：將藥品與基劑研合均勻成軟塊後，捏合成適宜形狀",
  "{{壓製法|名詞}}：取規定用量之藥品 ＋ 等量可可脂研合均勻，將其餘可可脂加入研合，製備成軟塊狀，放入壓栓器中壓製而得，適用{{對熱敏感藥物|名詞}}",
  "{{熔合法|名詞}}：取規定用量之藥品 ＋ 等量可可脂研合均勻，將其餘可可脂於水鍋上溫熱，攪拌均勻後放冷至 {{38°C|數值}}，立即倒入預先冷卻之模型中（內壁需塗{{潤滑油|物質}}），凝結而得",
  "熔合法：若某些藥物造成可可脂熔點下降，可添加少量{{硬脂酸鋁|物質}}改善；常用栓劑模具材質包含{{不銹鋼、黃銅、塑膠|物質}}等（玻璃被劃掉）",
  "儲存：≤ {{30°C|數值}}，{{密閉容器|名詞}}"
]);
