  "直徑：{{10nm|數值}}（100Å）",
  "優點：經皮擴散作用大，可{{促進藥品經皮吸收|名詞}}；可用於{{製造人工紅血球|名詞}}；與乳劑相比，液滴更易凝集，安定性佳",
