  "{{消泡劑|名詞}}（Antiforming agent）{{1-3|數值}}；{{W/O 乳劑|名詞}} {{3-6|數值}}；{{濕潤劑|名詞}}（Wetting agent）{{7-9|數值}}",
  "{{O/W 乳劑|名詞}} {{8-18|數值}}；{{清潔劑|名詞}}（Detergent）{{13-15|數值}}；{{助溶劑|名詞}}（Solubilizer）{{10-18|數值}}",
