  "製法：乳劑與{{內相（油）|名詞}}研合後，再將{{外相（水）|名詞}}加入內相",
  "流程：膠 ＋ 油（內相）→ 將水（外相）加入 → 加入其他物質或水至所需體積（膠先與{{油|物質}}混合，再將水加入混合）",
