  "沉降速率：凝絮化 {{快|性質}}；去凝絮化 {{慢|性質}}",
  "外型：凝絮化 {{上清液|名詞}}；去凝絮化 {{雲霧狀|名詞}}",
  "形狀：凝絮化 {{骨架狀|名詞}}；去凝絮化 {{塊狀|名詞}}",
