t(8, "膠體", 57, "colloid-basics", "膠體（Colloid）：簡介、分子量檢測、分類", "膠體概論", [
  "簡介：又稱{{膠狀分散體|名詞}}，可為{{單相|名詞}}（如親溶媒、微膠體）或{{兩相／非均相|名詞}}混合物（如斥溶媒膠體），兩相／非均相混合物含有兩種不同相的物質，被分散物質為{{分散相|名詞}}，連續分布物質為{{分散媒或媒液|名詞}}",
  "分子量：常用檢測儀器如{{超速離心機|名詞}}（測量沉降速率）、{{滲透壓儀|名詞}}（測量滲透壓）、{{濁度計|名詞}}（測量散射光）",
  "{{小分子溶液|名詞}}：粒徑 < {{1nm|數值}}；高滲透壓、擴散作用快；例：氯化鈉溶於水中",
  "{{膠體分散系|名詞}}：粒徑 {{2nm-1μm|數值}}（20Å-1μm）；可進行{{布朗運動|名詞}}、低滲透壓、擴散慢；例：皂土、微膠體、鎂乳漿",
  "{{粗分散系|名詞}}：粒徑 > {{1μm|數值}}；無滲透壓、無擴散作用；例：{{懸浮劑、乳劑|名詞}}"
]);
t(8, "膠體", 57, "specific-surface-area", "比表面積（Specific surface area, Ss）", "比表面積", [
  "定義：{{單位重量或單位體積之表面積|名詞}}",
  "{{單位體積比表面積|名詞}}（Volume-specific surface area, Sv）：Sv ＝ 總表面積／總體積 ＝ {{6/d|名詞}}（顆粒直徑）",
  "{{單位重量比表面積|名詞}}（Weight-specific surface area, Sw）：Sw ＝ 總表面積／總重量 ＝ 總表面積／（體積·密度）＝ {{6/（ρ·d）|名詞}}",
  "數值（Sv，比表面積 cm⁻¹）：邊長 1cm → {{6|數值}}；1mm → {{60|數值}}；0.1mm → {{600|數值}}；0.01mm → {{6000|數值}}"
], ["講義此表拍攝歪斜，邊長與比表面積的對應依 Sv ＝ 6/d 判讀"]);
t(8, "膠體", 57, "colloid-types", "膠體種類：親溶媒、斥溶媒、結合性", "膠體種類", [
  "{{親溶媒|名詞}}：特性：粒子可被分散媒{{溶解濕潤|性質}}；物質：{{阿拉伯膠／明膠溶於水中|物質}}",
  "{{斥溶媒|名詞}}：特性：粒子與分散媒{{較無交互作用|性質}}、對媒液黏度影響小；物質：{{無機物|物質}}（硫、砷、金、碘）",
  "{{結合性|名詞}}：特性：又稱{{界面活性劑|名詞}}，含親水基與親油基，可降低兩不相容液體之界面張力；物質：界面活性劑（陰離子、陽離子、非離子、兩性）"
], ["講義此表拍攝歪斜，特性與物質的對應依版面判讀"]);
t(8, "膠體", 58, "cloud-point", "Cloud point（曇點）", "曇點", [
  "簡介：加熱{{非離子性界面活性劑|物質}}至某一溫度時，外觀呈現{{混濁狀|性質}}，冷卻後恢復澄清之現象（加熱變混濁，冷卻變澄清）",
  "界面活性劑中，通常只有{{非離子型|名詞}}界面活性劑才會形成曇點",
  "特性：曇點與界面活性劑之{{溫度、組成|名詞}}有關（{{與濃度無關|性質}}）",
  "碳氫化合物之曇點與{{環氧乙稀數目|名詞}}呈{{正相關性|性質}}（環氧乙稀 ↑，曇點 ↑），與{{碳數|名詞}}呈{{負相關性|性質}}（碳數 ↑，曇點、CMC ↓）"
]);
t(8, "膠體", 58, "kraft-micelle", "Kraft point、微膠粒（微膠體、微胞）", "Kraft／微膠粒", [
  "{{Kraft point|名詞}}：界面活性劑在到達某一溫度下，{{溶解度|名詞}}迅速增加",
  "{{微膠粒|名詞}}成因：界面活性劑濃度增加，表面超量上升，在溶液中產生凝集所形成之凝集體",
  "微膠粒組成：由 {{50|數值}} 個單元體所組成；直徑：{{50 Å|數值}}",
  "功用：{{增加溶解度|名詞}}",
  "可逆性：屬於{{可逆|性質}}反應，加水稀釋後微膠體消失"
]);
t(8, "膠體", 59, "cmc", "臨界微膠粒濃度（Critical micelle concentration, CMC）", "CMC", [
  "定義：界面活性劑形成微膠體之{{最低濃度|名詞}}",
  "特性：碳數越高，表面張力越大，CMC 值越{{小|性質}}（所需濃度越低）；{{14|數值}} 個碳之化合物（C₁₄）所需 CMC 最小（C₁₄ < C₁₃, C₁₅ < C₁₂, C₁₆……）",
  "CMC 濃度值：{{C₁₀ > C₁₂ > C₁₄|名詞}}；溫度越高，CMC 越{{低|性質}}",
  "禁忌：陰、陽離子界面活性劑不可併用，易產生{{共聚化合物|名詞}}（Complex coacervation）；{{阿拉伯膠、明膠 Type B|物質}} 不可併用{{氯化苯甲烴銨|物質}}（Benzalkonium chloride）；{{皂土、高嶺土|物質}}（Kaolin）不可併用{{四級銨化合物|物質}}"
]);
t(8, "膠體", 59, "cmc-curves", "CMC 圖示：各物理量在 CMC 前後的變化", "CMC 曲線", [
  "A. {{表面張力|名詞}}：< CMC {{大量下降|性質}}；> CMC {{微降|性質}}",
  "B. {{界面張力|名詞}}：< CMC 大量下降；> CMC 微降",
  "C. {{滲透壓、冰點|名詞}}：< CMC {{大量增加|性質}}；> CMC {{微增|性質}}",
  "D. {{導電度、擴散係數|名詞}}：< CMC {{微降|性質}}；> CMC {{大量下降|性質}}",
  "E. {{溶解度|名詞}}（難溶性藥品）：< CMC {{趨近於 0|性質}}；> CMC {{大量增加（助溶）|性質}}",
  "說明：超過 CMC 時，溶解度大量增加，可能導致{{黏度、混濁度 ↑|性質}}（混濁度上升原因：內容物可分為高油性物質與可溶性物質，若微胞（含親油基 ＋ 親水基）溶解脂肪酸或高極性油脂，外觀呈{{混濁狀|性質}}，若微胞溶解可溶性物質，外觀呈現澄清狀）",
  "添加{{鹽類或電解質|物質}}可{{降低 CMC|名詞}}（降低顆粒間排斥力）；ABCDE 變化幅度 → {{A, B 最小，E 最大|名詞}}"
]);
t(8, "膠體", 60, "emulsify-vs-solubilize", "乳化作用（乳劑）vs 助溶作用（微膠體）", "乳化 vs 助溶", [
  "相同：添加界面活性劑、可形成 O/W 或 W/O 型",
  "種類：乳化 {{粗分散系、兩相|名詞}}；助溶 {{膠體分散系、單相|名詞}}",
  "顆粒：乳化 約 {{0.1-10μm|數值}}；助溶 約 {{10-100 Å|數值}}",
  "發生：乳化 {{無限制|性質}}（CMC 前後皆可）；助溶 {{> CMC|名詞}}",
  "外觀：乳化 {{乳白色|顏色}}；助溶（大多數）{{澄清透明|性質}}",
  "反應：乳化 {{外力作功|名詞}}；助溶 {{自發反應|名詞}}；性質：乳化 {{不安定|性質}}；助溶 {{安定|性質}}",
  "界面活性劑用量：乳化 {{小|性質}}；助溶 {{大|性質}}；蒸氣壓：乳化 {{不變|性質}}；助溶 {{下降|性質}}",
  "備註：微膠體助溶作用 ＝ 微膠體核心可使非水溶性分子或油溶性物質溶入，提升非水溶性物質溶解在水性媒液之量"
]);
t(8, "膠體", 60, "colligative", "依數性質（Colligative properties）", "依數性質", [
  "特性：依數性質與{{溶質粒子數|名詞}}有關（講義上「溶質特性」被劃掉）",
  "變數：{{蒸氣壓下降|名詞}}（Vapor pressure ↓）、{{凝固點／冰點下降|名詞}}（Freezing point ↓）、{{沸點上升|名詞}}（Boiling point ↑）、{{滲透壓改變|名詞}}（Osmotic pressure ↓↑）",
  "記法：蒸蝦（蒸氣壓下降）、瀕臨城下（冰點／凝固點下降）、飛升（沸點上升）、順便（滲透壓改變）"
]);
t(8, "膠體", 60, "tyndall-brownian-zeta", "廷得耳效應、布朗運動、Zeta 電位", "廷得耳／布朗", [
  "{{廷得耳效應|名詞}}（丁道爾效應, Tyndall effect）：當一束光線透過膠體時，自入射光垂直方向可發現膠體內部出現一條{{光亮通路|名詞}}；原理：光被懸浮之膠體粒子（例如：乳劑、懸浮劑）所{{散射|名詞}}；觀察：於光線之{{垂直|名詞}}方向觀察",
  "廷得耳效應物質：{{金溶膠|物質}}（斥溶媒膠體，帶{{負電|性質}}）；測量：{{分子量、形狀、大小|名詞}}（講義上「顏色、晶型」被劃掉）",
  "{{布朗運動|名詞}}（Brownian motion）：微小粒子或顆粒在流體中所進行之{{無規則運動|名詞}}（不規則碰撞）；粒徑：≤ {{5μm|數值}} 較容易產生",
  "布朗運動與{{絕對溫度、粒徑、黏度|名詞}}有關，與{{濃度|名詞}}無關",
  "{{Zeta 電位|名詞}}（Zeta potential）：為膠體粒子固定相與移動相之間電位差，電位大小隨表面距離增加而{{漸減|性質}}，可測量{{切變面／滑動面|名詞}}電位值"
]);
t(8, "依數性質計算", 61, "vant-hoff", "凡特荷夫定律（Van't Hoff law）", "凡特荷夫", [
  "公式：{{π ＝ C_M RT|名詞}}（π ＝ 滲透壓；C_M ＝ {{體積莫耳濃度|名詞}}；R ＝ 理想氣體常數；T ＝ 絕對溫度）",
  "內容：滲透壓與體積莫耳濃度、溫度成{{正比|性質}}，與分子量（M）成{{反比|性質}}",
  "修改公式：{{π/C ＝ BC ＋ RT/M|名詞}}（B ＝ 濃度係數（溶質-溶媒作用力）；M ＝ 分子量）；以 π/C 對 C 作圖，{{斜率 ＝ B、截距 ＝ RT/M|名詞}}、X 軸 ＝ C、Y 軸 ＝ π/C",
  "B > 0，溶質-溶媒吸引力 > 溶媒-溶媒吸引力；B ＝ 0，溶質-溶媒吸引力 ＝ 溶媒-溶媒吸引力（{{理想溶液|名詞}}）；B < 0，溶質-溶媒吸引力 < 溶媒-溶媒吸引力（{{容易發生沉澱|性質}}）",
  "R,T 固定時，{{截距越大，分子量越小|名詞}}；斜率{{越大|性質}}，粒子之間{{吸引力越大|性質}}；斜率 ＝ 0，表示粒子之間{{無吸引力|性質}}",
  "圖示：四條平行線 A、B、C、D 截距由大到小，分子量大小：{{D > C > B > A|名詞}}（截距越大，分子量越小）"
]);
t(8, "依數性質計算", 61, "colligative-formulas", "計算公式：冰點下降、蒸氣壓下降、拉午耳定律", "依數性質公式", [
  "{{冰點下降|名詞}}（凝固點下降）：ΔT_f ＝ {{K_f · C_m|名詞}}（ΔT_f，冰點下降量；K_f，冰點下降常數；C_m，{{重量莫耳濃度|名詞}}）",
  "{{蒸氣壓下降|名詞}}：ΔP ＝ {{P_A° · X_B|名詞}}（ΔP，蒸氣壓下降量；P_A°，{{純溶液蒸氣壓|名詞}}；X_B，{{溶質莫耳分率|名詞}}）",
  "{{拉午耳定律|名詞}}：P_i ＝ P_i° · X_i（P_i，溶液蒸氣壓；P_i°，純溶液蒸氣壓；X_i，{{溶劑莫耳分率|名詞}}）",
  "拉午耳定律：P ＝ P_A ＋ P_B ＝ {{P_A° · X_A ＋ P_B° · X_B|名詞}}（P，混合後蒸氣壓；P_A，A 成分蒸氣壓；P_B，B 成分蒸氣壓）"
]);
t(8, "膠體安定性與吸附", 62, "dlvo", "DLVO theory（Derjaguin-Landau-Verwey-Overbeek Theory）", "DLVO", [
  "簡介：說明{{斥溶媒膠體安定性|名詞}}，離子價數越高時，凝結作用越大，所需濃度越低",
  "濃度：最小凝結濃度與{{離子價數六次方之倒數|名詞}}成正比，相同價數下，分子量越大，所需濃度越低",
  "1 價：2 價：3 價 ＝ {{1/1⁶：1/2⁶：1/3⁶|名詞}}",
  "總結：價數越高，所需濃度{{越低|性質}}"
]);
t(8, "膠體安定性與吸附", 62, "gold-number", "Gold number（金數）", "金數", [
  "功用：評估{{保護性膠體之安定性|名詞}}",
  "原理：防止 {{1cm³（1ml）、10% 之 NaCl|數值}} 加入金溶膠內，導致 {{10cm³（10ml）|數值}} 紅色金溶膠體凝聚變為藍色，需加入保護性膠體的{{最少量|名詞}}（mg）（防止金溶膠自{{紅色|顏色}}凝集成{{藍色|顏色}}所需添加膠體之最少量）",
  "結論：金數越{{小|性質}}，保護力{{越強|性質}}"
]);
t(8, "膠體安定性與吸附", 62, "langmuir-bet", "Langmuir isotherm、BET 方程式", "Langmuir／BET", [
  "{{Langmuir 方程式|名詞}}：特性：較常用於{{單分子層|名詞}}吸附；C ＝ 濃度，X ＝ 吸附量，m ＝ 吸附劑吸附量",
  "圖 1 之 Y 軸表示每單位吸附劑所吸附溶質量（{{X/m|名詞}}），相同濃度下，A 所吸附的量大於 B",
  "圖 2 之 Y 軸表示每單位吸附劑所吸附溶質量之{{倒數|名詞}}（C/（X/m）），相同濃度下，1 的值大於 2，但由於倒數的關係（X/m 位置和圖 1 的 Y 軸相反），所以 {{2 的吸附量大於 1|名詞}}",
  "{{BET 方程式|名詞}}（Brunauer-Emmett-Teller equation）：測量固體或多孔性材料之{{比表面積|名詞}}，此理論將 Langmuir 單層吸附延伸至{{多分子層|名詞}}吸附",
  "BET：透過氣體（通常為 {{N₂|物質}}）在{{低溫|名詞}}下對樣品表面之物理吸附，計算出單分子層吸附量，從而計算出材料之總比表面積，常用於測量氣體吸附於固體或粉體之{{比表面積|名詞}}"
]);
t(8, "膠體安定性與吸附", 63, "gibbs-freundlich", "Gibbs 吸附方程式、Freundlich 方程式", "Gibbs／Freundlich", [
  "{{Gibbs 吸附方程式|名詞}}：描述{{界面活性劑在兩相之間吸附作用|名詞}}；公式：Γ ＝ {{−（C/RT）（dγ/dc）|名詞}}（Γ，表面超量；C，濃度；R，氣體常數；T，絕對溫度；γ，表面張力）",
  "Γ > 0 表示{{正向吸附|名詞}}，可{{降低|性質}}界面張力，dγ/dc < 0；Γ < 0 表示{{負向吸附|名詞}}，會{{增加|性質}}界面張力，dγ/dc > 0",
  "{{Freundlich 方程式|名詞}}：描述吸附劑溶質濃度與液相溶質濃度之關係；特性：{{雙對數圖|名詞}}作圖為{{直線|名詞}}"
]);
