  "{{普維酮碘溶液|物質}}（Povidone Iodine）：又稱{{優碘|名詞}}，外用藥；特性：{{I₂ ＋ PVP|物質}} 之穩定錯合物；含量：含碘 {{85-120%|數值}}；濃度 {{10%|數值}}；pH {{1.5-6.5|數值}}",
