  "{{氫氧化鈣溶液|物質}}（石灰水, Lime water）：特性：溫度升高，溶解度{{降低|性質}}；製造：取氫氧化鈣 {{3g|數值}} 加入蒸餾水，共製成 1000mL；保存：{{緊密容器|名詞}}（吸收空氣中 CO₂ 形成 {{CaCO₃|物質}} 沉澱）"
