  "{{次乙酸鋁溶液|物質}}（Aluminum subacetate topical solution）：組成：{{硫酸鋁、乙酸以及沉澱性碳酸鈣|物質}}反應而成；添加：可添加 {{0.9% 硼酸|物質}}增加穩定性",
  "次乙酸鋁溶液分類：常作為局部外用製劑，可製備成{{洗劑、潤濕劑|名詞}}；比較：{{Burow's solution|名詞}} 又稱 {{Aluminum acetate|物質}} topical solution"
