ch(16, "生物製劑", "108～111");
t(16, "生物製劑", 108, "biologics-basics", "生物製劑：簡介、製造、儲存、片段", "生物製劑概論", [
  "簡介：由生物所製造或提取之藥物和醫療產品，可藉由抑制體內特定發炎因子，治療免疫疾病等症狀；當抗原進入體內時，會使 {{B 淋巴球|名詞}}增生並分泌抗體",
  "製造：{{重組 DNA|名詞}}（rDNA）技術可用來生產蛋白質藥物",
  "儲存：{{2-8°C|數值}}；片段：對同一抗體而言，其 {{Sfv|名詞}} 片段通常都會比 Fab′ 片段{{小|性質}}",
  "免疫反應：可分為自然免疫、獲得免疫、主動免疫、被動免疫等；製劑分類：包含{{疫苗、類毒素|名詞}}等"
]);
t(16, "生物製劑", 108, "biologic-drugs", "藥物：反義藥物、蛋白類藥物", "生物藥物", [
  "{{反義藥物|名詞}}（Antisense drugs）：抑制細胞合成更多所需之標的蛋白質，或使細胞無法產生所需之標的蛋白質；結構可能為{{單股 DNA 或雙股 RNA|名詞}}；{{Vitravene|藥名}} 為第一個成功上市 Antisense therapy 藥物",
  "{{蛋白類藥物|名詞}}：{{Adalimumab、Aldesleukin、Etanercept、Epoetin alpha、Interferon α-2b、Trastuzumab|藥名}}"
]);
t(16, "生物製劑", 108, "biologic-stabilizers", "安定劑（生物製劑）", "生物製劑安定劑", [
  "{{Ascorbic acid|物質}}，可協助{{穩定蛋白質構型|性質}}（也可作為抗氧化劑）",
  "{{Aspartic acid|物質}}，可抑制{{異構化|反應}}反應（也可用於製造甜味劑）",
  "{{Polysorbate 20|物質}}，可延遲{{凝集|反應}}反應（也可作為界面活性劑）",
  "{{Mannitol|物質}}，防止冷凍（{{抗凍劑|名詞}}）",
  "{{Leucine|物質}}（白胺酸），具疏水性及表面活性，常用於抑制顆粒凝集（Aggregation）、改善粉末流動性及分散性",
  "{{Ethanolamine|物質}}（乙醇胺），常作為{{緩衝劑或 pH 調節劑|名詞}}"
]);
t(16, "生物製劑", 108, "biologics-other", "生物製劑：其他重點", "生物製劑其他", [
  "{{生物相似藥|名詞}}為與原開發的分子複製物（Clone）{{不同|性質}}",
  "{{單株抗體|名詞}}（Monoclonal antibody）相對於多株抗體，具有更高{{一致性和重複性|性質}}",
  "Recombinant DNA 可用於生產許多蛋白質或 DNA 類生物製劑",
  "疫苗透過{{微脂體|名詞}}遞送可減少副作用並增強有效性",
  "製備抗毒素或治療蛇毒之免疫血清時，通常用{{馬|名詞}}作為試驗動物",
  "美國第一個核准之鼻噴霧劑疫苗為 {{Live influenza virus vaccine|藥名}}"
]);
t(16, "免疫", 109, "adjuvants-cryo", "佐劑（Adjuvants）、冷凍保存劑（CPAs）", "佐劑／冷凍保存劑", [
  "{{佐劑|名詞}}：為疫苗可能組成之一，其主要功能為協助誘發、延長或增強對目標抗原產生特異性以及免疫反應",
  "佐劑物質：製備疫苗常使用之佐劑為{{氫氧化鋁|物質}}（Aluminum hydroxide）；{{鋁鹽|物質}}佐劑（如氫氧化鋁、磷酸鋁）為最早獲得主管機關所核准使用之佐劑，可增加抗原呈現，提高抗體；{{卡介菌|物質}}（BCG）也可作為佐劑使用",
  "{{冷凍保存劑|名詞}}（Cryoprotectant agents, CPAs）：{{滲透型|名詞}}（細胞內）：{{二甲基亞碸（DMSO）、甘油、丙二醇、甲醇|物質}}",
  "{{非滲透型|名詞}}（細胞外）：{{蔗糖、海藻糖（Trehalose）、聚乙烯吡咯烷酮（PVP）、羥乙基澱粉|物質}}"
]);
t(16, "免疫", 109, "immunity-types", "免疫種類：自然、獲得、主動、被動免疫", "免疫種類", [
  "{{自然免疫|名詞}}（Natural immunity）：又稱{{先天免疫|名詞}}；用非特異性的方式抵抗外來感染源，在體內進行初期防禦的免疫反應，與{{種族免疫、個體免疫|名詞}}有關",
  "{{獲得免疫|名詞}}（Acquired immunity）：又稱{{後天免疫|名詞}}；自然免疫無法有效消滅病原時，淋巴球、巨噬細胞會產生特異性免疫反應，辨識外來抗原，並啟動 T 細胞和 B 細胞（啟動順序：{{Macrophage → T cells → B cells|名詞}}）",
  "獲得免疫：特異性免疫可分為{{細胞免疫與體液免疫|名詞}}，細胞免疫由 {{T 細胞|名詞}}主導，主要攻擊受感染細胞、癌細胞與移植細胞；體液免疫由 {{B 細胞|名詞}}主導，受抗原刺激後會釋出抗體；獲得免疫可分為{{主動免疫與被動免疫|名詞}}",
  "{{主動免疫|名詞}}（Active immunity）：{{抗原|名詞}}進入個體時，所引發之免疫反應；自然主動免疫 → {{麻疹、猩紅熱|疾病}}；人工主動免疫 → {{注射疫苗、類毒素|名詞}}等，使個體產生免疫力，多用於{{預防|名詞}}",
  "{{被動免疫|名詞}}（Passive immunity）：{{抗體|名詞}}進入個體時，促使個體產生免疫力對抗抗原；自然被動免疫 → 抗體自然進入個體內，如{{母體經由胎盤將抗體送入胎兒|名詞}}中；人工被動免疫 → 注射特定抗體，產生免疫反應，如{{免疫血清、免疫球蛋白、抗毒素|名詞}}"
]);
t(16, "疫苗與類毒素", 110, "vaccines", "製劑：免疫球蛋白與各種疫苗", "疫苗製劑", [
  "{{人體免疫血清球蛋白|物質}}：一種非特效丙種免疫球蛋白（{{IgG|名詞}} 抗體），以{{胺基乙酸|物質}}做為安定劑（穩定球蛋白），可用於免疫缺陷（如低丙球蛋白血症）、自體免疫性疾病、急性感染，屬於{{被動免疫|名詞}}反應",
  "{{卡介苗|物質}}：Bacillus Calmette-Guérin（BCG）vaccine，用於預防{{結核病|疾病}}之疫苗，疫苗內結核桿菌之菌種為{{乾燥活菌|名詞}}",
  "{{人類乳突病毒疫苗|物質}}：Human papillomavirus（HPV）vaccine，預防人類乳突病毒感染所導致之{{子宮頸癌|疾病}}、陰莖癌以及肛門癌等",
  "{{破傷風白喉非細胞性百日咳疫苗|物質}}：Diphtheria tetanus toxoid with acellular pertussis（DtaP），將破傷風和白喉桿菌所分泌之毒素減毒製成類毒素，與百日咳抗原成份混合而成",
  "{{麻疹腮腺炎德國麻疹混合疫苗|物質}}：Measles Mumps and Rubella（MMR），預防麻疹、腮腺炎、德國麻疹之{{活性減毒|名詞}}疫苗",
  "{{狂犬病疫苗|物質}}：Rabies vaccine，保護暴露於狂犬病高危環境之人員，如獸醫、狂犬病實驗室工作人員等",
  "{{傷寒疫苗|物質}}：Typhoid vaccine，一種{{不活化|名詞}}疫苗，現今使用之疫苗為純化傷寒桿菌細胞壁多醣體所製成",
  "{{破傷風免疫球蛋白|物質}}：Tetanus Immune Globulin（TIG），治療破傷風發病，或對未接種疫苗／高風險傷口提供緊急保護，屬於{{被動免疫|名詞}}反應",
  "{{破傷風類毒素|物質}}：將破傷風桿菌（Clostridium tetani）產生之外毒素，經{{甲醛|物質}}（Formaldehyde）處理（去毒化／減毒）而得"
]);
t(16, "疫苗與類毒素", 110, "toxoids", "試劑、多合一疫苗、類毒素（Toxoids）", "類毒素", [
  "試劑 {{甲醛|物質}}：可消除生物製劑毒素毒性，同時保留{{抗原性|名詞}}（Antigenicity），使其可刺激免疫系統產生抗體，但{{不會導致疾病|性質}}",
  "{{三合一疫苗|名詞}}：{{破傷風、白喉、百日咳|疾病}}；{{四合一疫苗|名詞}}：破傷風、白喉、百日咳、{{小兒麻痺|疾病}}；{{五合一疫苗|名詞}}：破傷風、白喉、百日咳、小兒麻痺、{{b 型嗜血桿菌|疾病}}",
  "{{類毒素|名詞}}（Toxoids）簡介：一種細菌毒素（多為{{外毒素|名詞}}），經化學處理後，毒性已被抑制，但仍保留其抗原性",
  "製備：將細菌增殖後，毒素之濾液經由{{過濾、鹽析、清洗、透析純化|名詞}}，再以{{甲醛|物質}}去除毒性；特性：可與其他類毒素或疫苗混合施打",
  "單位：強度單位為{{凝絮單位|名詞}}（Flocculating, Lf）"
]);
t(16, "微脂體與生物相似藥", 111, "liposome", "微脂體（Liposome）：SUV、LUV、MLV", "微脂體", [
  "微脂體：{{磷脂雙層|名詞}}所形成之球形囊泡，常用於藥物遞送系統",
  "{{SUV|名詞}}（Small Unilamellar Vesicles，小型單層囊泡）：粒徑約 {{0.02-0.2 μm|數值}}；{{一層|數值}}磷脂質雙層膜所組成，常用於藥物傳遞與靶向治療",
  "{{LUV|名詞}}（Large Unilamellar Vesicles，大型單層囊泡）：粒徑約 {{0.2-10 μm|數值}} 以上；一層磷脂質雙層膜（{{單層|性質}}磷脂質雙分子層）；適合包覆{{水溶性藥物|名詞}}（外膜只有單層，因此囊泡內部包覆一個連續且體積較大之水性空間，可在水相核心中裝載較多液體）；成分比例：{{內部水相|名詞}}比例較高",
  "{{MLV|名詞}}（Multilamellar Vesicles，多層囊泡）：粒徑約 0.2-10 μm 以上；{{多層|性質}}磷脂質雙層膜所組成（{{洋蔥狀|名詞}}構造）；適合包覆{{脂溶性藥物|名詞}}（多層脂質膜將內部水性空間分隔成許多不連續、各自獨立之小水相隔間，提供較大比例脂質體積，將藥物卡在層層脂質雙層膜中）；成分比例：{{內部脂質膜|名詞}}比例較高"
]);
t(16, "微脂體與生物相似藥", 111, "generic-vs-biosimilar", "學名藥（Generic）vs 生物相似藥（Biosimilar）", "學名藥 vs 生物相似藥", [
  "分子大小：學名藥 {{小分子|性質}}（如 Aspirin）；生物相似藥 {{大分子蛋白質|性質}}（如 Monoclonal antibodies）",
  "結構：學名藥 {{可完全一致|性質}}（Identical）；生物相似藥 {{高度相似|性質}}（Highly similar）{{但非完全一致|性質}}",
  "製造方法：學名藥 {{化學合成|名詞}}（穩定、可預測）；生物相似藥 {{細胞培養|名詞}}（複雜、具變異性）",
  "臨床數據要求：學名藥 {{僅需 BE 試驗|名詞}}；生物相似藥 {{需 PK/PD 及臨床療效試驗|名詞}}",
  "免疫原性（Immunogenicity）：學名藥 {{極低|性質}}；生物相似藥 {{嚴格監測|名詞}}（蛋白質可能誘發免疫反應）",
  "其他：生物相似藥 具{{高度異質性|性質}}（Heterogeneity），常被視為{{混合物|名詞}}而非單一原料藥"
]);

/* ===== 第 17 章 試驗與檢查法（拍攝第 112～130 頁）===== */
ch(17, "試驗與檢查法", "112～130");
t(17, "安定性試驗", 112, "stability-testing", "安定性試驗", "安定性試驗", [
  "{{長期試驗|名詞}}：{{25°C±2°C、60%RH±5%RH|數值}}、儲存時間 {{12 個月|數值}}",
  "{{中間試驗|名詞}}：{{30°C±2°C、65%RH±5%RH|數值}}、儲存時間 12 個月",
  "{{加速試驗|名詞}}：{{40°C±2°C、75%RH±5%RH|數值}}、儲存時間 {{6 個月|數值}}",
  "備註：RH ＝ Relative Humidity，{{相對濕度|名詞}}"
]);
t(17, "劑型單元含量均一度試驗", 112, "dosage-uniformity", "劑型單元含量均一度試驗（第八版名稱：單位劑量均一度）", "劑型單元均一度", [
  "摘要：為確保劑型單元之一致性，每批次中每單位之原料藥應在標誌含量範圍內，「劑型單元」定義為在每個單位劑型中所含單一劑量或原料藥之部分劑量，「劑型單元含量均一度」定義為劑型單元中原料藥之均一程度",
  "劑型單元含量均一度可透過兩種方法表現：{{含量均一度試驗或重量差異試驗|名詞}}，含量均一度試驗可應用於{{所有情況|名詞}}，本試驗之規格不適用於外用、皮膚給藥之單一劑量容器中之懸液、乳劑或凝膠",
  "分類：有效成分 < {{25mg|數值}} 或重量佔錠劑總重 < {{25%|數值}} → {{含量均一度|名詞}}試驗；有效成分 ≥ 25mg 及重量佔錠劑總重 ≥ 25% → {{重量差異|名詞}}試驗",
  "重量差異試驗適用劑型：{{W1|名詞}}：包裝在單一劑量容器或軟膠囊中之{{溶液|名詞}}；{{W2|名詞}}：包裝在單一單位容器中且不含活性或非活性添加物質之固體（含粉末、顆粒及無菌固體）",
  "{{W3|名詞}}：包裝在具有或不具有活性或非活性添加物質之單一單位容器中之固體（含無菌固體），其由真實溶液製備並於最終容器中{{冷凍乾燥|名詞}}並標註以表明該製備方法",
  "{{W4|名詞}}：硬膠囊、未包衣錠劑或薄膜錠劑含 {{25 mg|數值}} 或更多原料藥，或以硬膠囊為例之膠囊含量為 {{25%|數值}} 或更多之重量組成，除其他原料藥之均一性以較少比例存在外，達到含量均一性之要求",
  "不符合上述重量差異試驗條件之所有劑型，均需進行{{含量均一度試驗|名詞}}"
]);
t(17, "劑型單元含量均一度試驗", 113, "cu-wv-table", "含量均一度（CU）與重量差異（WV）試驗對照表", "CU／WV 對照", [
  "錠劑：未包衣 ≥25mg 及 ≥25% → {{WV|名詞}}，< 25mg 或 < 25% → {{CU|名詞}}；包衣-薄膜 → WV／CU；包衣-其他 → {{CU|名詞}}／CU",
  "膠囊：硬 → {{WV|名詞}}／CU；軟-懸液劑／乳劑／凝膠 → {{CU|名詞}}／CU；軟-{{溶液|名詞}} → {{WV|名詞}}／{{WV|名詞}}",
  "單一劑量容器中固體：單一成分 → WV／WV；多成分-最後容器中冷凍乾燥溶液 → {{WV|名詞}}／{{WV|名詞}}；多成分-其他 → CU／CU",
  "單一劑量容器與軟膠囊中溶液 → {{WV|名詞}}／{{WV|名詞}}；其他 → CU／CU"
], ["講義此表拍攝歪斜，各欄 WV／CU 依版面對齊判讀"]);
t(17, "劑型單元含量均一度試驗", 113, "acceptance-value", "劑型單元含量均一度之共同允收標準、允收值（AV）", "允收值 AV", [
  "（適用於含量均一度試驗及符合重量差異試驗條件之劑型）",
  "第一次 {{10 個|數值}}：允收值 ≤ {{15%|數值}}，即符合規定；允收值超過 15%，再取 {{20 個|數值}}檢品，進行第二次",
  "第二次 {{30 個|數值}}：須同時滿足兩個條件才算符合規定：1. 全部 30 個檢品{{最終允收值 ≤ 15%|名詞}}；2. 個別含量須介於 [1 − 0.01（L2）]M 與 [1 ＋ 0.01（L2）]M 之間，L2 ＝ {{25.0|數值}}（除非另有規定）",
  "計算公式：{{AV ＝ |M − X| ＋ ks|名詞}}；X（個別含量之平均值）：抽測檢品（10 個或 30 個）之含量平均值",
  "M（{{參考值|名詞}}）：根據平均值（X）與目標含量（T）而變動之數值，可衡量平均含量是否落在合格中心區間內（大多預設 M ＝ {{100%|數值}}）",
  "k（{{允收常數|名詞}}）：根據抽樣數量給定之統計常數，測試數量為 10 個（第一階段），k ＝ {{2.4|數值}}；測試數量為 30 個（第二階段），k ＝ {{2|數值}}",
  "s（{{樣品標準偏差|名詞}}）：測試單元含量之標準差，可代表該批藥品每顆之間差異（離散）程度"
]);
t(17, "最低內容量測定", 114, "minimum-fill", "最低內容量測定（適用於乳膏／凝膠／洗劑／軟膏／糊劑／粉劑／氣化噴霧劑等製劑）", "最低內容量", [
  "（中華藥典第八版名稱：{{最低內容量試驗法|名詞}}）",
  "第一次 {{10 個|數值}}：≤ {{60 g（ml）|數值}}：10 件檢品之平均淨含量均{{不得|性質}}低於標誌含量（低於標誌含量即為不合格）；任一檢品淨含量不得低於標誌含量 {{90%|數值}}，若不符合此條件，進行第二次（階段二）試驗",
  "第一次 10 個：≥ 60 g（ml）：10 件檢品之平均淨含量均不得低於標誌含量；任一檢品淨含量不得低於標誌含量 {{95%|數值}}，若不符合此條件，進行第二次試驗",
  "第二次 {{30 個|數值}}：≤ 60 g（ml）：30 件檢品之平均內容量均不得低於標誌含量；低於標誌含量 90% ≤ {{1 個|數值}}；符合上述兩項才算合格",
  "第二次 30 個：≥ 60 g（ml）：30 件檢品之平均內容量均不得低於標誌含量；低於標誌含量 95% ≤ 1 個；符合上述兩項才算合格",
  "備註：{{淨含量 ＝ 淨重；內容量 ＝ 填充量|名詞}}（這兩個詞的概念跟意思相近～視為同一個概念即可）",
  "範例 1（標誌含量 50g）：抽驗 10 支檢品分別為 51g, 52g, 49g, 50g, 51g, 48g, 50g, 51g, 49g, 50g；平均值 50.1g（達到 100%）；最輕 48g（超過 45g，沒有低於 90%）；判定：{{合格|名詞}}",
  "範例 2（標誌含量 50g）：抽驗 10 支檢品分別為 48g, 50g, 46g, 50g, 46g, 47g, 49g, 48g, 49g, 47g；平均值 {{48g|數值}}（未達 50g）；最輕 46g（超過 45g，沒有低於 90%）；判定：{{不合格|名詞}}"
]);
t(17, "溶離試驗", 115, "dissolution-test", "溶離試驗：簡介與允收標準", "溶離試驗", [
  "簡介：測定錠劑或膠囊中有效成分於規定溶媒及試驗條件下，在指定時間內之溶出速率或程度；可用於{{藥品品質管制|名詞}}（檢測藥物品質一致性）、{{批次間釋放一致性評估|名詞}}（生產批次之釋放均一性）、{{預測體內藥物釋放表現|名詞}}以及藥物配方篩選之參考依據",
  "第一次 {{6 個|數值}}：每一檢品主成分溶離量 ≥ {{Q ＋ 5%|名詞}}",
  "第二次 {{12 個|數值}}：平均主成分溶離量 ≥ Q，且無檢品主成分溶離量低於 {{Q − 15%|名詞}}",
  "第三次 {{24 個|數值}}：平均主成分溶離量 ≥ Q，主成分溶離量低於 Q − 15% 不超過 {{2|數值}} 個，無檢品主成分溶離量低於 {{Q − 25%|名詞}}",
  "裝置：裝置 I：{{籃式裝置|名詞}}；裝置 II：{{槳式裝置|名詞}}"
]);
t(17, "溶離試驗", 115, "apparatus-1", "溶離度試驗裝置 I（籃式裝置）相關條件", "裝置 I 條件", [
  "溫度 {{37±0.5°C|數值}}；篩網 {{40 號|數值}}篩網；網籃孔徑 {{0.36-0.44 mm|數值}}；軸心偏差 ≤ {{2mm|數值}}",
  "馬達轉速：依各該品目規定，裝置 I 可設定之轉速範圍約 {{25~150 rpm|數值}}",
  "底部距離 {{25±2 mm|數值}}；溶媒體積（通常）{{3 倍飽和體積|數值}}；指定轉速誤差 低於 {{±4%|數值}}"
]);
t(17, "溶離試驗", 116, "dissolution-apparatus", "溶離試驗裝置（Apparatus 1～7）", "溶離裝置 1～7", [
  "溶離試驗裝置可評估藥品{{安全品質與有效性|名詞}}",
  "{{Apparatus 1|名詞}}：{{轉籃法、籃式法|名詞}}（Rotating basket method）：{{固體口服劑型最常使用|性質}}（如錠劑、膠囊）、部分栓劑；{{37°C±0.5°C|數值}}",
  "{{Apparatus 2|名詞}}：{{槳式法|名詞}}（Paddle method）：固體口服劑型最常使用（如錠劑、膠囊）、部分栓劑；37°C±0.5°C",
  "{{Apparatus 3|名詞}}：{{圓筒型往復式法|名詞}}（Reciprocating cylinder method）：{{咀嚼錠、軟膠囊、遲釋劑型|名詞}}、非崩散型產品（如包衣小球）；37°C±0.5°C",
  "{{Apparatus 4|名詞}}：{{川流槽式法、流通池法|名詞}}（Flow through cell method）：活性成分溶解度有限之控釋或原態釋放劑型（{{難溶性藥品|名詞}}）、軟膠囊、栓劑、連珠狀藥品、懸浮型延釋劑型；37°C±0.5°C",
  "{{Apparatus 5|名詞}}：{{槳盤式法|名詞}}（Paddle over disk method）：{{經皮給藥製劑|名詞}}（Transdermal drug products）；{{32°C±0.5°C|數值}}",
  "{{Apparatus 6|名詞}}：{{圓筒型旋轉式法|名詞}}（Rotating Cylinder method）：經皮給藥製劑；32°C±0.5°C",
  "{{Apparatus 7|名詞}}：{{支架型往復式法|名詞}}（Reciprocating holder method）（舊稱：往復碟法、往復圓盤法，Reciprocating disk method）：經皮給藥製劑 {{32°C±0.5°C|數值}}；{{控釋劑型、非崩散劑型、植入劑|名詞}} {{37°C±0.5°C|數值}}（依劑型及各品目規定）"
]);
t(17, "溶離試驗", 117, "dissolution-methods", "溶離試驗方法一、方法二（腸溶劑型）", "溶離方法一二", [
  "{{方法一|名詞}} 酸性液段：取 {{0.1 N 鹽酸 750 mL|數值}} 作為媒液，待媒液平衡至 37±0.5°C 後加入樣品，{{2 小時|數值}}後取出部分溶液檢驗，按照緩衝液段繼續試驗",
  "方法一 緩衝液段：取酸性液段溶液，加入 {{0.2 M 磷酸三鈉|物質}}溶液 {{250 mL|數值}}（可使用 2 N 鹽酸或 2 N 氫氧化鈉調整 pH 值至 {{6.8±0.05|數值}}），並平衡至 37±0.5°C，試驗 {{45 分鐘|數值}}後，取出部分溶液測定主成分溶解量（註：當緩衝液全部加入後，應於 {{5 分鐘內|數值}}測 pH 值）",
  "{{方法二|名詞}} 酸性液段：取 {{0.1 N 鹽酸 1000 mL|數值}} 作為媒液，待媒液平衡至 37±0.5°C 後加入樣品，2 小時後取出部分溶液檢驗，按照緩衝液段繼續試驗",
  "方法二 緩衝液段：取酸性液段溶液，加入 0.1 N 鹽酸：0.2 M 磷酸三鈉溶液（{{3：1|數值}}）混合之 pH 6.8 {{磷酸鹽|物質}}緩衝液 1000 mL（可使用 2 N 鹽酸或 2 N 氫氧化鈉調整 pH 值至 6.8±0.05），試驗 45 分鐘後，取出部分溶液測定主成分溶解量"
]);
t(17, "溶離試驗", 117, "enteric-acceptance", "酸性液段／緩衝液段合格範圍", "腸溶合格範圍", [
  "{{酸性液段|名詞}} 第一次 {{6 個|數值}}：{{每個|名詞}}檢品主成分溶解量均無超過規定量之 {{10%|數值}}",
  "酸性液段 第二次 {{12 個|數值}}：全部 12 個檢品平均溶解量未超過規定量之 10%，且無檢品之溶解量超過 {{25%|數值}}",
  "酸性液段 第三次 {{24 個|數值}}：全部 24 個檢品平均溶解量未超過規定量之 10%，且無檢品之溶解量超過 25%",
  "{{緩衝液段|名詞}} 第一次 6 個：每個檢品主成分溶解量不低於 {{Q ＋ 5%|名詞}}",
  "緩衝液段 第二次 12 個：全部 12 個檢品平均溶解量 ≥ Q，且無檢品之溶解量低於 {{Q − 15%|名詞}}",
  "緩衝液段 第三次 24 個：全部 24 個檢品平均溶解量 ≥ Q，溶離量低於 Q − 15% 不超過 {{2|數值}} 個，且無檢品溶解量低於 {{Q − 25%|名詞}}"
]);
t(17, "崩散試驗", 118, "disintegration-test", "崩散試驗：摘要、允收、相關條件", "崩散試驗", [
  "摘要：測量錠劑或膠囊是否能在規定時間內崩散，崩散並非指整個劑型或所含有效成分完全溶解，完全崩散係指狀態{{除了不溶性塗層之碎片或膠囊外殼|名詞}}，留存於測定器或黏附之殘留物已呈{{稀軟團塊且無可覺察之硬質|性質}}",
  "第一次 {{6 個|數值}}：全部崩散；第二次 {{18 個|數值}}：至少 {{16 個|數值}}完全崩散",
  "相關條件：裝置 {{筒狀網籃|名詞}}；溫度 {{37±2°C|數值}}；篩網 {{10 號|數值}}；每分鐘升降 每分鐘 {{29~32 週期|數值}}（大約 30±2 次）；軸心偏差 ≤ {{2mm|數值}}",
  "網架提升高度 {{5.3~5.7cm|數值}}（上升至最高點時，篩網維持於液面下至少 {{15 mm|數值}}）（下降至最低點時，篩網距離容器底部至少 {{25 mm|數值}}）"
]);
t(17, "崩散試驗", 118, "disintegration-time", "崩散時間與崩散 vs 溶離比較", "崩散時間", [
  "崩散時間：依各品目規定，部分劑型列舉如下：{{口服溶液用發泡錠、發泡性顆粒|名詞}} → {{5 分鐘|數值}}，或依個論規定",
  "{{遲釋錠與膠囊劑|名詞}}（以耐酸或腸衣配製）（{{具可溶性外部糖衣者|名詞}}）→ 先於室溫水中浸泡 {{5 分鐘|數值}}，再進行酸性階段",
  "遲釋錠與膠囊劑（以耐酸或腸衣配製）（{{無糖衣者|名詞}}）→ 直接以「{{酸性階段|名詞}}」進行測試",
  "比較：溫度 崩散 {{37±2°C|數值}}／溶離 {{37±0.5°C|數值}}；篩網 崩散 {{10 號|數值}}／溶離 裝置 I：{{40 號|數值}}篩網",
  "比較：速率 崩散 {{30±2 次/min|數值}}／溶離 轉速 25-150 rpm；底部距離 崩散 ≥ {{25 mm|數值}}／溶離 {{25±2 mm|數值}}；數量 崩散 {{6 ＋ 12 ＝ 18|數值}}／溶離 {{6 ＋ 6 ＋ 12 ＝ 24|數值}}"
]);
t(17, "BCS 生物藥劑學分類", 119, "bcs", "BCS 生物藥劑學分類", "BCS 分類", [
  "{{Class I|名詞}}：溶解度 {{高|性質}}、穿透係數 {{高|性質}}；建立體外溶離與體內生體可用率相關性（IVIVC）{{最適合|性質}}；測定 {{崩散|名詞}}",
  "{{Class II|名詞}}：溶解度 {{低|性質}}、穿透係數 {{高|性質}}；IVIVC {{最有可能|性質}}；測定 {{溶離|名詞}}",
  "{{Class III|名詞}}：溶解度 {{高|性質}}、穿透係數 {{低|性質}}；IVIVC {{最不適合|性質}}；測定 {{吸收|名詞}}",
  "{{Class IV|名詞}}：溶解度 {{低|性質}}、穿透係數 {{低|性質}}；IVIVC {{最不可能|性質}}"
]);
t(17, "BCS 生物藥劑學分類", 119, "ich-m9", "歐盟 ICH M9 指引：重點整理", "ICH M9", [
  "具有 {{BCS Class 1、Class 3|名詞}} 特性之原料藥",
  "BCS {{高穿透性|名詞}}（High permeability）之判定，應先以人體藥動學研究所推得之吸收程度為依據，例如絕對生體可用率或質量平衡研究，當絕對生體可用率 ≥ {{85%|數值}}時，可判定為高穿透性",
  "當投與劑量中有至少 {{85%|數值}}可於尿液以原型藥物回收，或原型藥物加上尿液中回收之 Phase 1 氧化代謝物與 Phase 2 結合代謝物形式回收時，可支持高穿透性判定結果（糞便中原型藥物原則上不直接計入評估吸收程度）",
  "{{Caco-2|名詞}} 細胞試驗可作為高穿透性之體外支持方法，模型藥物依人體吸收程度可分為 < {{50%（低）|數值}}、{{50-84%（中）|數值}}、≥ {{85%（高）|數值}}",
  "若只用 Caco-2 結果判定高穿透性，應證明藥物穿透性{{不依賴主動轉運|性質}}，因此較適用於主要經{{被動擴散|藥動}}吸收之藥物",
  "藉由{{裝置一|名詞}}（Apparatus 1，{{100 rpm|數值}}）或{{裝置二|名詞}}（Apparatus 2，{{50 rpm|數值}}）於 pH {{1.2、4.5 及 6.8|數值}} 進行比較性溶離試驗時：",
  "1. BCS Class I：試驗品與參考品皆於 {{15 分鐘|數值}}內平均溶離 ≥ 85%（{{極快速溶離|名詞}}）；若 {{30 分鐘|數值}}內平均溶離 ≥ 85%（{{快速溶離|名詞}}），則須再確認試驗品是否與參考品之溶離曲線相似（{{f₂ ≥ 50|名詞}}）",
  "2. BCS Class III：試驗品與參考品皆於 {{15 分鐘|數值}}內平均溶離 ≥ 85%（極快速溶離）",
  "（註）{{f₂|名詞}}（Similarity factor，相似因子）：用於比較試驗品與參考品之溶離曲線相似性；f₂ ≥ {{50|數值}} 表示兩者溶離曲線相似"
]);
t(17, "BCS 生物藥劑學分類", 120, "ich-q6a-ivivc", "ICH Q6A、評估 BCS 滲透性、IVIVC", "Q6A／IVIVC", [
  "{{ICH Q6A|名詞}}：對速放固體口服製劑，符合下列條件時，可考慮以{{崩散試驗取代溶離試驗|名詞}}：1. 藥物於 pH {{1.2-6.8|數值}} 範圍內具有{{高溶解度|性質}}（Dose/solubility volume ≤ {{250 mL|數值}}）；Dose/solubility volume ＝ 最高單次劑量（mg）÷ 該 pH 下之溶解度（mg/mL）（可想成是：最高單次劑量所需溶解液體積）",
  "ICH Q6A：2. 於 pH {{1.2、4.0 及 6.8|數值}} 中，{{15 分鐘|數值}}內溶離 ≥ {{80%|數值}}標示含量之藥物成分",
  "評估 BCS 滲透性：1. In situ intestinal perfusion study in {{rats|名詞}}；2. In vitro permeation experiments across a monolayer of cultured {{Caco-2 cells|名詞}}；3. In vivo intestinal perfusion studies in {{humans|名詞}}",
  "{{體外體內相關性|名詞}}（In Vitro-In Vivo Correlations, IVIVC），可評估藥品品質與臨床表現",
  "Level {{A|名詞}}：{{體外溶離百分比曲線 ＋ 體內吸收百分比曲線|名詞}}（體外溶離量-體內吸收量經時變化相關性）；生物藥劑 {{Wagner-Nelson、Loo-Riegelman|名詞}}",
  "Level {{B|名詞}}：體外{{平均溶離時間|名詞}}、體內{{平均滯留時間|名詞}}（體外體內平均溶離時間）；生物藥劑 {{MDT、MRT|名詞}}",
  "Level {{C|名詞}}：{{特定時間溶離量、體內參數|名詞}}；生物藥劑 {{AUC、Cmax|名詞}}",
  "備註：MDT ＝ Mean Dissolution Time（平均溶離時間）；MRT ＝ Mean Residence Time（平均滯留時間）；{{持續釋放錠|名詞}}（控制釋放錠、延長釋放錠）劑型為建立 IVIVC 之主要關鍵步驟"
]);
t(17, "眼用與注射劑檢查", 121, "ophthalmic-metal-particles", "眼用軟膏金屬粒子檢測（第八版：眼用軟膏金屬粒子檢查法）", "金屬粒子檢測", [
  "摘要：取檢品 {{10 支|數值}}，將內容物分別擠入十個平底無刮痕之培養皿中，加蓋後加溫至 {{85°C|數值}}，保持 {{2 小時|數值}}，待檢品完全液化，注意勿使液體搖動，將培養皿逐一取下，於室溫平置至凝成固體",
  "置備經校正之{{分厘測微計目鏡|名詞}}，可調適觀測放大 {{30 倍|數值}}之顯微鏡，加裝可與檢體調成 {{45 度角|數值}}之照明燈，將作成之檢品各皿逐一反置於顯微鏡平台上，變動入射光強度，由金屬粒子{{光反射|名詞}}特性，將培養皿底全部檢視之",
  "計算大小為 {{50 μm|數值}} 與以上各形粒子之數目：10 檢品中，含 {{8 粒|數值}}以上者，不得超過 {{1 個|數值}}，粒子總數不得超過 {{50 個|數值}}；如不符規定，則再取檢品 20 支檢查，全部 30 支檢品中，大小為 50 μm 與以上各形粒子 8 粒以上者，不得超過 {{3 個|數值}}，粒子總數不得超過 {{150 個|數值}}",
  "第一次 10 個：≥ 50 μm 金屬粒子數超過 8 粒以上之軟膏管數 ≤ {{1 管|數值}}；≥ 50 μm 粒子總數 ≤ {{50 粒|數值}}",
  "第二次 30 個：≤ {{3 管|數值}}；≤ {{150 粒|數值}}"
]);
t(17, "眼用與注射劑檢查", 121, "particulate-matter", "微粒物質檢查法、眼用溶液劑微粒物質檢測", "微粒物質檢查", [
  "{{≤ 100 ml|數值}}：{{光阻法|名詞}} ≥ 10 μm ≤ {{6000 個/每容器|數值}}、≥ 25 μm ≤ {{600 個/每容器|數值}}；{{鏡檢法|名詞}} ≥ 10 μm ≤ {{3000 個/每容器|數值}}、≥ 25 μm ≤ {{300 個/每容器|數值}}",
  "{{> 100 ml|數值}}：光阻法 ≥ 10 μm ≤ {{25 個/每 ml|數值}}、≥ 25 μm ≤ {{3 個/每 ml|數值}}；鏡檢法 ≥ 10 μm ≤ {{12 個/每 ml|數值}}、≥ 25 μm ≤ {{2 個/每 ml|數值}}",
  "備註：大多採用{{光阻法|名詞}}檢測，{{鏡檢法|名詞}}適用{{高黏度、低澄明度、抽檢時易產生氣泡／氣體|性質}}者",
  "{{眼用溶液劑|名詞}}微粒物質檢測（光阻法／鏡檢法微粒物質限值）：≥ 10 μm {{50 個/ml|數值}}；≥ 25 μm {{5 個/ml|數值}}；≥ 50 μm {{2 個/ml|數值}}"
]);
t(17, "注射劑容器檢測", 122, "glass-container-tests-1", "玻璃容器：水侵蝕度試驗、可溶性鹼釋出試驗", "水侵蝕度／鹼釋出", [
  "{{水侵蝕度試驗|名詞}}：測量{{完整玻璃容器|名詞}}（針對{{不打碎|性質}}之完整容器趁熱進行）",
  "試劑／試液：{{高純度水|物質}}（25°C 傳導度須小於 {{0.15μS/cm|數值}}）、{{甲基紅試液|物質}}（酸鹼指示劑）、{{0.02 N 硫酸|物質}}（趁熱時滴定玻璃所釋放出的鹼）",
  "器械：{{高壓蒸氣滅菌器|名詞}}，恆溫 {{121°C±2°C|數值}}",
  "{{可溶性鹼釋出試驗|名詞}}：將玻璃容器{{打碎|性質}}成特定大小顆粒，測試玻璃材質整體之耐水解度（而非僅測玻璃內表面）；試劑／試液、器械同水侵蝕度試驗；以 {{0.02N 硫酸|物質}}滴定"
]);
t(17, "注射劑容器檢測", 122, "glass-container-tests-2", "玻璃容器：砷試驗、可溶性鐵試驗、透光度試驗、鉛含量試驗", "砷／鐵／鉛試驗", [
  "{{砷試驗|名詞}}：所用溶液為取用{{可溶性鹼釋出試驗|名詞}}所得之玻璃萃取液（將玻璃打碎成顆粒，加入高純度水並經過 121±2.0°C 高壓蒸氣滅菌 30 分鐘之萃取液），以化學呈色方法來進行",
  "砷試驗試劑／試液：7N 硫酸、碘化鉀、氯化亞錫、異丙醇、{{二乙胺基二硫甲酸銀|物質}}；微量砷被還原為{{胂氣體|物質}}後，胂氣體與二乙胺基二硫甲酸銀試液作用，形成{{紅色|顏色}}錯合物，檢品溶液所產生之紅色色澤，不得比標準溶液產生之紅色色澤更深",
  "砷試驗：檢品每 g 限量為 {{0.1 ppm（0.1 μg）|數值}}；儀器測定：可使用分光光度計於最大吸收波長約 {{535~540 nm|數值}} 測量吸光度",
  "{{可溶性鐵試驗|名詞}}：針對{{阻光性容器|名詞}}檢測；試劑：{{0.01 N 鹽酸|物質}}；檢品溶液所呈現顏色不得比標準品溶液{{更深|性質}}；{{琥珀色|顏色}}玻璃較容易溶出鐵",
  "{{透光度試驗|名詞}}：檢驗{{阻光性容器|名詞}}是否具備合格避光防護能力",
  "{{鉛含量試驗|名詞}}：使用可溶性鹼釋出試驗所得之水萃取液，進行{{硫化物沉澱|反應}}反應；取檢品溶液 10 mL，與{{鹽酸|物質}} 1 滴與{{硫化鈉|物質}}試液 3 滴後，不得呈現{{褐色|顏色}}"
]);
t(17, "注射劑容器檢測", 123, "pe-pp-container", "塑膠容器：聚乙烯（PE）、聚丙烯（PP）", "PE／PP 容器", [
  "簡介：{{不含任何添加物|性質}}，容器內無附著或黏附物",
  "透光度：於波長 {{450 nm|數值}} 測定，透光率不得低於 {{55%|數值}}；外觀：不得有摺痕、破裂、氣泡或瑕疵",
  "{{濕氣滲透試驗|名詞}}：取 {{12 個|數值}}檢品，加水密封後，於相對濕度 {{65±5%|數值}}、溫度 {{20±2°C|數值}} 放置 {{14 天|數值}}，減失重量不得超過 {{0.2%|數值}}",
  "重金屬：限量為 {{2 ppm|數值}}；熾灼殘渣：遺留殘渣不得超過 {{0.1%|數值}}；可浸出物：{{121°C|數值}} 高壓滅菌 {{1 小時|數值}}"
]);
t(17, "注射劑容器檢測", 123, "pvc-container-tests", "塑膠容器：聚氯乙烯（PVC）、其他材質", "PVC 容器檢測", [
  "簡介：應以{{氯乙烯同元聚合物|物質}}為原料，{{不得含黏合劑|性質}}；除了須符合與聚乙烯、聚丙烯容器相同之透光度、外觀、濕氣滲透、重金屬、熾灼殘渣、可浸出物等試驗，也須檢測下列項目",
  "厚度：於{{五個|數值}}不同處測量，最大值與最小值不得超過 {{0.05 mm|數值}}",
  "{{漏裂試驗|名詞}}：將待測容器加滿{{螢紅鈉鹽|物質}}溶液並緊密封閉，上下處鋪墊濾紙，於 {{20°C|數值}} 下，以 {{6.9 N/cm²|數值}} 加壓 {{10min|數值}}，濾紙不得呈色",
  "彈性：插入輸注用針頭，在{{不注入空氣置換|名詞}}之情形下，容器中之溶液應可完全排出",
  "微粒物質：加入生理食鹽水，經 121°C 高壓滅菌 25 分鐘，冷卻 2 小時候，常溫靜置 24 小時，以{{光阻法|名詞}}檢測（每 mL 檢出 {{5~10 μm|數值}} 者不得超過 {{100 個|數值}}，{{10~25 μm|數值}} 不得超過 {{1 個|數值}}，不得含有 {{25 μm|數值}} 以上顆粒）",
  "{{其他材質|名詞}}：除應符合聚乙烯、聚丙烯容器之重金屬、熾灼殘渣、可浸出物規定，還須符合透光度、外觀、濕氣滲透以及{{細胞毒素|名詞}}等規定"
]);
t(17, "滅菌法（中華藥典第九版）", 124, "sterilization-overview", "滅菌法：簡介、殺傷力、分類", "滅菌法概論", [
  "簡介：以適當程序使產品達到無菌狀態，並可使微生物及其芽孢失活或死亡",
  "殺傷力：{{濕熱法 > 乾熱法|名詞}}；溫度／時間：{{乾熱法 > 濕熱法|名詞}}（通常濕熱滅菌之熱傳遞效率較乾熱滅菌佳，因此在相同滅菌效果下，可使用較低溫度或較短時間）",
  "{{蒸氣滅菌|名詞}}：{{115°C-116°C 加熱 30 min|數值}}、{{121°C 加熱 20 min|數值}}、{{126°C 加熱 15 min|數值}}",
  "{{乾熱滅菌|名詞}}：{{160°C 加熱 60 min/2 hr|數值}}；{{油液／油質滅菌|名詞}}：{{150°C 加熱 60 min|數值}}",
  "{{氣體滅菌|名詞}}：{{Ethylene oxide|物質}}（環氧乙烯／環氧乙烷）、過氧化氫、過乙酸；{{游離輻射滅菌|名詞}}：{{γ-ray、電子束、X 射線|名詞}}；{{過濾滅菌|名詞}}：{{0.22 μm|數值}}"
]);
t(17, "滅菌法（中華藥典第九版）", 124, "steam-sterilization", "蒸氣滅菌（Steam sterilization）", "蒸氣滅菌", [
  "簡介：以{{飽和蒸氣|名詞}}進行滅菌，可用於開放、包覆或密閉容器之物品",
  "機制：飽和蒸氣凝結時傳遞熱能，並藉水合作用造成微生物{{蛋白質變性凝固|名詞}}",
  "條件：115°C-116°C 加熱 30 min；121°C 加熱 20 min；126°C 加熱 15 min",
  "生物指示劑：{{Geobacillus stearothermophilus|菌種}}（嗜熱脂肪芽孢桿菌）",
  "適用：{{溶液劑、耐熱水性製劑、培養基以及可耐受濕熱之物品|名詞}}；溫度：量測於蒸氣{{出口處|名詞}}",
  "備註：{{無法去除細菌內毒素或其他熱原|性質}}（去除熱原可用{{乾熱滅菌法|名詞}}）"
]);
t(17, "滅菌法（中華藥典第九版）", 125, "dry-heat-sterilization", "乾熱滅菌（Dry Heat Sterilization）", "乾熱滅菌", [
  "機制：以乾熱方式經對流、輻射或直接熱傳遞進行滅菌；可造成微生物{{氧化與脫水|名詞}}",
  "條件：{{容器滅菌|名詞}}：{{160°C|數值}} 以上，至少加熱 {{60 min|數值}}（只能殺死微生物與芽孢，無法破壞熱原）；{{一般滅菌|名詞}}：160°C 以上，至少加熱 {{2 hr|數值}}（只能殺死微生物與芽孢，無法破壞熱原）",
  "{{去除熱原|名詞}}：高於 {{220°C|數值}}（常用於去除{{玻璃器皿|名詞}}之熱原），以具有熱抗性之內毒素進行確效時，內毒素須達到 {{3 個 log10 衰減|名詞}}（減少 {{99.9%|數值}}）（如果原本有 1000 單位內毒素，經 3 個 log10 衰減後，剩下 1 單位）",
  "補充條件（工業用／實務上）：去除熱原 {{250°C，加熱 30 min|數值}}；眼用軟膏（空管滅菌）{{175°C 加熱 2 hr|數值}}",
  "生物指示劑：{{Bacillus atrophaeus|菌種}}（枯草芽孢桿菌）",
  "適用：{{甘油、石蠟、液體石蠟（礦物油）、氧化鋅|物質}}等油溶性物質；{{玻璃器皿、金屬容器|名詞}}（講義上「塑膠類容器、橡皮」被劃掉）；非揮發性油類、耐熱油性製劑、耐熱非水性製劑以及對熱安定物質",
  "備註：一般橡皮塞可用 {{0.5% Sodium pyrophosphate|物質}}（焦磷酸鈉）之熱水溶液清洗"
]);
t(17, "滅菌法（中華藥典第九版）", 125, "oil-gas-sterilization", "油液／油質滅菌、氣體滅菌（蒸氣相滅菌）", "油質／氣體滅菌", [
  "{{油液、油質滅菌|名詞}}：機制：利用{{油或油酸乙酯|物質}}加熱；條件：內容物{{不超過 30 ml|數值}} 於 {{150°C 加熱 60 min|數值}}；內容物{{超過 30 ml|數值}} 需延長總加熱時間，使容器內全部內容物{{均達到 150°C|名詞}} 後，維持 150°C 至少 60 min",
  "{{氣體滅菌劑|名詞}}：{{烷化劑|名詞}}：{{環氧乙烯／環氧乙烷|物質}}（Ethylene oxide），但具有{{可燃性、細胞毒性、致突變性（致癌性）、爆炸性|副作用}}（可加入惰性氣體（如 {{CO₂|物質}}）稀釋以降低爆炸性）；滅菌後須充分排除殘留氣體及相關副產物",
  "氣體滅菌劑 {{氧化劑|名詞}}：高反應性之毒性物質，如{{過氧化氫與過乙酸|物質}}",
  "機制：環氧乙烯可藉由{{烷化作用|名詞}}與蛋白質胺基、硫醇基、羥基以及核酸鹼基反應，造成微生物失去活性（烷化細菌蛋白質、干擾細胞代謝）",
  "生物指示劑：環氧乙烷滅菌 {{Bacillus atrophaeus|菌種}}；蒸氣型過氧化氫 {{Geobacillus stearothermophilus|菌種}}",
  "適用：{{直接性包材、設備及部分藥品之表面滅菌|名詞}}（歷屆試題曾出現過：醫療用插管、對熱或濕氣不安定物質、最終包裝產品之滅菌）",
  "替代：近年改用 {{Chlorine dioxide|物質}}（二氧化氯）取代 Ethylene oxide"
]);
t(17, "滅菌法（中華藥典第九版）", 126, "radiation-filtration", "游離輻射滅菌、過濾滅菌", "輻射／過濾滅菌", [
  "{{游離輻射滅菌|名詞}}（Ionizing radiation sterilization）（早期名稱：放射滅菌）：機制：利用{{伽馬射線|名詞}}（γ-ray，如{{鈷 60|物質}}）、電子束或 X 射線進行滅菌；可造成微生物 {{DNA 損傷|名詞}}而失去活性",
  "游離輻射滅菌 生物指示劑：一般不需使用生物指示劑；但特殊情況（如組織或細胞製劑，或產品成分可能保護孢子時），可能須使用生物指示劑（建議使用 {{Bacillus pumilus|菌種}}）",
  "{{過濾滅菌|名詞}}（Filtration Sterilization）：機制：利用{{過篩|名詞}}方式，以適當之濾菌器過濾，並於無菌狀態下封入已滅菌容器",
  "過濾滅菌 待測微生物：使用孔徑不超過 {{0.22 μm|數值}} 之過濾系統時，建議使用 {{Brevundimonas diminuta|菌種}}（缺陷短波單胞菌）；孔徑 {{0.1 μm|數值}} 或更小系統時，建議使用 {{Acholeplasma laidlawii|菌種}}（萊氏黴漿菌）",
  "備註：待測微生物 ＝ 拿哪一種菌來測；生物指示劑 ＝ 將待測微生物以特定菌數、載體、包裝或培養系統製成的標準化測試系統",
  "過濾滅菌 適用：無法以最終容器滅菌之產品，例如{{對熱不安定溶液及無菌調配注射劑|名詞}}；過濾程序須經確效，並監控過濾前之微生物污染量、過濾時間／體積、壓力差以及濾膜完整性等因子",
  "過濾滅菌 優點：所需時間短、適用{{臨時調配、無菌調配|名詞}}之注射藥品、可於室溫下進行滅菌；孔徑 {{0.22 μm|數值}}（［比較］微孔濾膜過濾法孔徑 {{0.45 μm|數值}}）"
]);
t(17, "滅菌法（中華藥典第九版）", 126, "sterilization-summary", "滅菌法小整理", "滅菌法小整理", [
  "{{蒸氣滅菌|名詞}}：微生物{{蛋白質變性凝固|名詞}}；115°C-116°C 加熱 30 min、121°C 加熱 20 min、126°C 加熱 15 min",
  "{{乾熱滅菌|名詞}}：促使微生物{{氧化與脫水|名詞}}；容器：160°C 加熱 60 min；一般：160°C 加熱 120 min；去除熱源：高於 {{220°C|數值}}",
  "{{氣體滅菌|名詞}}：{{烷化蛋白質、干擾代謝|名詞}}；環氧乙烯、過氧化氫、過乙酸",
  "{{游離輻射滅菌|名詞}}：微生物 {{DNA 損傷|名詞}}；γ-ray、電子束、X 射線",
  "{{過濾滅菌|名詞}}：利用{{過篩方式濾除微生物|名詞}}；0.22 μm"
]);
t(17, "生物指示劑與滅菌參數", 127, "biological-indicators", "生物指示劑（Biological indicator）（中華藥典第九版）", "生物指示劑", [
  "{{蒸氣滅菌、濕熱滅菌|名詞}}：{{Geobacillus stearothermophilus|菌種}} #真是氣人（蒸，濕，Ge）",
  "{{乾熱滅菌|名詞}}：{{Bacillus atrophaeus|菌種}} #乾爸錯了（乾，ba，tro）",
  "{{氣體滅菌|名詞}} 環氧乙烷：{{Bacillus atrophaeus|菌種}} #氣壞巴菲特（氣，環，ba，phae）；過氧化氫：{{Geobacillus stearothermophilus|菌種}} #氣養雞屎（氣，氧，Ge，st）",
  "{{游離輻射滅菌|名詞}}：一般不需考慮生物指示劑，但特定情況可使用 {{Bacillus pumilus|菌種}} #扶 puma（輻，pumi）",
  "{{過濾滅菌|名詞}}：不超過 0.22 μm {{Brevundimonas diminuta|菌種}} #過濾 2 個笨蛋（過濾，0.22，bre，di）；不超過 0.1 μm {{Acholeplasma laidlawii|菌種}} #過濾 1 顆（過濾，0.1，cho）",
  "中華藥典第八版（歷屆試題用）：乾熱滅菌法 {{Bacillus subtilis|菌種}}；氣體滅菌法 {{Bacillus subtilis var. niger|菌種}}（現名：Bacillus atrophaeus）；濕熱、高壓蒸氣滅菌法 {{Bacillus stearothermophilus|菌種}}（現名：Geobacillus stearothermophilus）；過濾滅菌法 {{Pseudomonas diminuta|菌種}}（現名：Brevundimonas diminuta）"
]);
t(17, "生物指示劑與滅菌參數", 127, "d-value-release", "滅菌動力參數（D 值）、釋放速率設計", "D 值", [
  "{{D 值|名詞}}（decimal reduction time）係指在某一滅菌條件下，微生物活菌數減為原菌數 {{1/10|數值}} 所需時間（滅菌 {{90%|數值}}所需時間）",
  "特性：D 值與{{溫度|名詞}}有關，達到「無菌」所需時間至少需 {{12D|數值}}",
  "{{釋放速率設計|名詞}}：半衰期{{短|性質}}者以{{控釋劑型|名詞}}（控制釋放錠）設計較佳，半衰期約 {{4~6 小時|數值}}，治療指數宜 > {{10|數值}}",
  "半衰期{{長|性質}}者以{{速效劑型|名詞}}設計較佳"
]);
t(17, "滅菌檢查法（無菌試驗）", 128, "direct-inoculation", "直接接種法與培養基", "直接接種法", [
  "簡介：當檢品不適用{{微孔濾膜過濾法|名詞}}時，可採用直接接種法進行無菌試驗，操作方式為將檢品（或其懸浮液）以無菌操作抽取、浸泡或混勻於適當培養基中",
  "{{硫醇乙酸鹽培養基 I|名詞}}（澄明液體）：{{30~35°C|數值}}；{{金黃色葡萄球菌|菌種}}（Staphylococcus aureus）（好氧菌）、{{綠膿桿菌|菌種}}（Pseudomonas aeruginosa）（好氧菌）、{{產芽孢梭菌|菌種}}（Clostridium sporogenes）（{{厭氧菌|名詞}}）",
  "{{硫醇乙酸鹽培養基 II|名詞}}（混濁、黏性液體）：30~35°C；產芽孢梭菌（Clostridium sporogenes）（厭氧菌）",
  "{{大豆分解蛋白質-乾酪素培養基|名詞}}：{{20~25°C|數值}}；{{枯草桿菌|菌種}}（Bacillus subtilis）（好氧菌）、{{白色念珠菌|菌種}}（Candida albicans）（黴菌）、{{巴西麴菌|菌種}}（Aspergillus brasiliensis）（黴菌）",
  "其他：若培養基混濁，須於培養 {{14 日|數值}}後，取適當量（不少於 1 mL）移置新鮮培養基，原瓶與新瓶繼續培養至少 {{4 日|數值}}（以確定是否有微生物生長）；檢品體積不可超過培養基體積之 {{10%|數值}}",
  "適用：大多數{{醫療器材|名詞}}（除了具管路者）"
]);
t(17, "滅菌檢查法（無菌試驗）", 128, "sterility-test-types", "無菌試驗：培養天數、測試目的、合格標準", "無菌試驗種類", [
  "{{產品常規無菌試驗|名詞}}：至少 {{14 日|數值}}；檢測產品本身是否遭受污染；期間內無微生物生長",
  "{{培養基無菌性確認|名詞}}：至少 {{14 日|數值}}；檢測培養基本身是否無菌；期間內無微生物生長",
  "{{培養基效能試驗|名詞}}：細菌不超過 {{3 日|數值}}、黴菌不超過 {{5 日|數值}}；檢測培養基本身是否可長菌；加入之活菌必須生長良好",
  "{{抑菌性／抑黴菌性確效試驗|名詞}}：細菌不超過 3 日、黴菌不超過 5 日；檢測{{藥品是否會干擾微生物生長|名詞}}；加入之活菌必須生長良好"
]);
t(17, "滅菌檢查法（無菌試驗）", 129, "membrane-filtration", "微孔濾膜過濾法", "微孔濾膜過濾法", [
  "過濾器：由過濾瓶與裝有微孔濾膜之漏斗組成，可無菌過濾檢品；油類檢品之過濾器使用前須{{完全乾燥|名詞}}",
  "濾膜材質：{{纖維素硝酸鹽|物質}}（Cellulose nitrate），適用於含{{水性、油性與低乙醇濃度|名詞}}檢品；{{纖維素乙酸鹽|物質}}（Cellulose acetate），適用於{{高乙醇濃度|名詞}}檢品；抗生素類檢品使用具有{{抵消抗生素作用|名詞}}之濾膜",
  "孔徑：不超過 {{0.45μm|數值}}；適用：{{對熱不安定溶液|名詞}}（講義上「醫療器材無菌試驗檢查」被劃掉）；時間：培養觀察至少 {{14 日|數值}}",
  "微孔濾膜過濾法檢查藥品（列舉部分藥物）（中華藥典第九版）：注射用節絲菌素 B（{{Amphotericin B|藥名}} for Injection）、胺苄青黴素（{{Ampicillin|藥名}}）、注射用亞茲索絲菌素（Azithromycin for Injection）、苄青黴素鈉鹽（Benzylpenicillin Sodium）",
  "咖啡因檸檬酸鹽注射液、咖啡因檸檬酸鹽口服溶液、注射用卡必西林（Carbenicillin for Injection）、注射用西福西汀（Cefoxitin for Injection）、氯絲菌素注射液（Chloramphenicol Injection）",
  "{{新絲菌素硫酸鹽-培尼皮質醇乙酸酯眼用懸液|名詞}}（Neomycin Sulfate and Prednisolone Acetate Ophthalmic Suspension）、新絲菌素硫酸鹽-皮質醇乙酸酯眼用軟膏（Neomycin Sulfate and Hydrocortisone Acetate Ophthalmic Ointment）、舒巴坦鈉鹽（Sulbactam Sodium）"
]);
t(17, "冷凍乾燥法", 130, "lyophilization", "冷凍乾燥法（凍晶乾燥法, Lyophilization）", "冷凍乾燥法", [
  "原理：先將製劑冷凍，再於低壓下使冰直接{{昇華|反應}}，以移除大部分水分；其後經二次乾燥去除吸附水分，常用於提升不安定藥品之安定性與保存性，可用於製備{{乾粉注射劑|名詞}}",
  "添加：經常加入 {{Mannitol|物質}} 增加體積（常作為{{填充劑|名詞}}）；特性：乾燥後可形成晶型／非晶型產物，{{非晶型|名詞}}產物通常較容易吸濕，因此須採用適當防潮包裝",
  "溫度：{{三相點|名詞}}（{{0.0099°C, 4.57mmHg|數值}}）以下；物質：{{對熱不安定|性質}}物質（如蛋白質、生物製劑、疫苗、胰島素、部分抗生素及血液製劑等）",
  "缺點：製程時間長、{{設備成本高|性質}}、能源耗用較高，且需嚴格控制產品溫度與真空條件",
  "藥品：使用 {{Zydis|名詞}} 技術 → {{Claritin Reditabs, Maxalt-MLT, Zofran ODT|藥名}}",
  "流程：{{冷凍 → 一次乾燥（減壓昇華）→ 二次乾燥（脫附）→ 真空或充填惰性氣體下封塞 → 封口|名詞}}",
  "將原料冷凍凝固（大多介於 {{-10~-40°C|數值}}），再進行抽氣以降低蒸氣壓（減壓）使冷凍物質蒸氣化（昇華）；接著把水分由冰昇華移除，去除水分後，卸除真空、恢復常溫即可",
  "二次乾燥時，可在真空環境下逐步加熱，加速水分移除（{{脫附|反應}}）作用"
]);

/* ===== 第 18 章 補充資料（拍攝第 131～138 頁）===== */
ch(18, "補充資料", "131～138");
t(18, "度量衡", 131, "units", "度量衡", "度量衡", [
  "長度：1 inch（吋）＝ {{2.54 公分|數值}}；1 foot（呎）＝ {{12 吋|數值}}（約 30 公分）；1 yard（碼）＝ {{3 呎|數值}}（約 90 公分）",
  "重量：1 公斤 ＝ {{2.2 磅|數值}}（pound, lb）；1 磅（Pound）＝ {{454 g|數值}}；1 盎司（Ounce, oz）＝ {{28.4 g|數值}}；1 grain ＝ {{64.8 mg|數值}}",
  "體積：1 加侖（Gallon）＝ {{3785 ml|數值}}；1 品脫（Pint）＝ {{473 ml|數值}}；1 湯匙（Tablespoon）＝ {{15 ml|數值}}；1 茶匙（Teaspoon）＝ {{5 ml|數值}}；滴管 20 滴 ＝ {{1 g|數值}}",
  "其他：{{最小秤取量 ＝ 靈敏度需求／誤差值|名詞}}；靈敏度需求 X g → 表示此儀器最精確可量測至 X g 之差異，若低於 X g 則誤差較大；25°C 水的密度 ＝ {{1g/cm³|數值}}",
  "備註：d ＝ {{十分之一|數值}}，d ＋ 單位 ＝ 0.1 × 單位；1 dg ＝ 0.1 g、1 dL ＝ 0.1 L ＝ {{100 ml|數值}}、1 dm ＝ 0.1 m ＝ 10 cm；c ＝ {{百分之一|數值}}，c ＋ 單位 ＝ 0.01 × 單位；1 cg ＝ 0.01 g、1 cL ＝ 0.01 L ＝ 10 ml、1 cm ＝ 0.01 m"
]);
t(18, "度量衡", 131, "density-vs-sg", "密度（Density, ρ）vs 比重（Specific Gravity）", "密度 vs 比重", [
  "定義：密度 {{單位體積內之質量|名詞}}；比重 規定溫度下，物質密度與參考物質密度之比值，液體通常以{{水|物質}}為參考物",
  "計算：密度 ρ ＝ {{質量／體積|名詞}}；比重 ＝ {{物質密度／參考物質密度|名詞}}（物質重量／同體積參考物質重量）",
  "單位：密度 {{有單位|性質}}（如 g/mL, kg/m³）；比重 {{無單位|性質}}（單純比值）",
  "備註：密度 數值隨{{溫度|名詞}}改變而不同；比重 藥典一般以 {{25°C|數值}} 為標準測定溫度"
]);
t(18, "CYP450", 132, "cyp450", "CYP450 代謝酵素與受質", "CYP450", [
  "{{CYP 1A2|名詞}}：{{Theophylline, Fluvoxamine, Imipramine, Amitriptyline, Clozapine, Olanzapine, Caffeine|藥名}}；{{Fluvoxamine|藥名}} 主要經 CYP1A2 代謝，也是強力 CYP1A2、CYP2C19 抑制劑；增加 1A2 代謝：{{吸菸、炭烤肉類、十字花科蔬菜（花椰菜）|名詞}}",
  "{{CYP 2C8|名詞}}：Repaglinide, Imatinib, Loperamide, Montelukast, Paclitaxel, Pioglitazone, Rosiglitazone；{{Gemfibrozil|藥名}}（降血脂藥）為 CYP2C8 強力抑制劑，併用 {{Repaglinide|藥名}} 可能引發嚴重{{低血糖|副作用}}",
  "{{CYP 2C9|名詞}}：{{S-warfarin|藥名}}, Tolbutamide, Ticlopidine, Glipizide, Ibuprofen, Diclofenac, Losartan, Phenytoin（次要經由 CYP2C19 代謝，亦為 MDR1 受質）；{{菠菜、花椰菜|名詞}}及維生素 K 含量較高之深綠色蔬菜，可能因增加維生素 K 攝取而降低 Warfarin 抗凝效果，使 INR 下降",
  "{{CYP 2C19|名詞}}：Omeprazole, Lansoprazole, S-mephenytoin, Diazepam；{{Clopidogrel|藥名}}（{{前驅藥|名詞}}，經 2C19 活化）；{{CYP2C19*17|名詞}} 會導致 Clopidogrel 代謝物濃度上升，增加出血風險；{{亞洲人|族群}}有較多 CYP2C19 poor metabolizer",
  "{{CYP 2D6|名詞}}：{{Codeine、Clonidine、Dextromethorphan|藥名}}（常考）、Desipramine, Desbrisoquine, Tolterodine, Promethazine, SSRI（Fluoxetine, Paroxetine）、TCA（Nortriptyline, Amitriptylin, Imipramine）、Propranolol（2D6 為主，2C19 為輔）、Tramadol、{{Tamoxifen|藥名}}（經 2D6 活化為 {{Endoxifen|物質}}）",
  "CYP 2D6：{{Codeine|藥名}} 經 2D6 代謝成 {{Morphine|藥名}}（產生止痛效果）；帶有 {{CYP2D6*4|名詞}} 基因型患者，服用 Tamoxifen 可能{{降低治療效果|副作用}}；若使用 {{Tolterodine|藥名}} 可能使血中濃度上升，增加中樞副作用",
  "{{CYP 3A4|名詞}}（{{種類最多|性質}}）：Erythromycin, Clarithromycin, Ketoconazole, Cisapride, Cyclosporine, Diazepam, Felodipine, Midazolam, Triazolam, R-Warfarin, Simvastatin, Lovastatin, Atorvastatin；抑制 3A4 代謝：{{葡萄柚|名詞}}",
  "備註：{{Isoniazid|藥名}} 所引起{{紅斑性狼瘡|疾病}}（lupus erythematosus）與 {{N-acetyltransferase|名詞}} 有關"
]);
t(18, "補充資料", 133, "temperature-terms", "溫度（°C）（中華藥典第九版）", "溫度名詞", [
  "除另有規定外，均以{{攝氏 25°C|數值}}為標準",
  "{{微溫|名詞}} {{30~40°C|數值}}；{{常溫|名詞}} {{15~30°C|數值}}；{{涼處|名詞}} {{8~15°C|數值}}；{{冷處、低溫|名詞}} ≤ {{8°C|數值}}；{{冷藏|名詞}} {{2~8°C|數值}}；{{冷凍|名詞}} {{-25~-10°C|數值}}",
  "{{控溫室|名詞}} ≤ {{25°C|數值}}；{{受控室溫|名詞}} {{20~25°C|數值}}；{{溫暖|名詞}} {{30°C~40°C|數值}}；{{過熱|名詞}} {{40°C 以上|數值}}"
]);
t(18, "補充資料", 133, "isopropyl-aminophylline", "擦洗用異丙醇、Aminophylline 與 Theophylline", "異丙醇／Aminophylline", [
  "{{Isopropyl rubbing alcohol|物質}}（擦洗用異丙醇）：濃度：非特定對象使用之最適當濃度範圍約 {{68-72%|數值}}（可記 {{70%|數值}}），其餘成分為{{水|物質}}，亦可含有經核可之安定劑、芳香油、色素添加劑",
  "擦洗用異丙醇：比重 20°C 時約 {{0.88|數值}}（0.872~0.883）；功用：{{外用防腐殺菌劑|名詞}}（糖尿病患者大多使用 {{90%|數值}} Isopropyl rubbing alcohol 消毒注射針劑等器材）；標誌：應註明為{{可燃性液體|名詞}}",
  "{{Aminophylline|藥名}} ＝ {{2 Theophylline ＋ 1 Ethylenediamine|物質}}；功用：{{支氣管擴張劑|藥效}}",
  "溶解度：{{Aminophylline > Theophylline|名詞}}（Aminophylline 溶解度約為 Theophylline {{20-25 倍|數值}}）"
]);
t(18, "控釋系統", 134, "oros", "Osmotic controlled release oral delivery system（OROS）", "OROS", [
  "簡介：OROS 是藉由{{滲透壓|名詞}}的技術，將藥物以控制速度之方式釋出；錠劑最外層為{{不溶性半透膜|名詞}}，頂端包含兩個{{鐳射小孔|名詞}}（釋出藥物），內部共有三層，由上而下依序為不同藥物濃度之{{藥物層、推動層|名詞}}，推動層含滲透壓成分，可協助推動藥物以定時定量之方式釋出（{{零階次釋放|名詞}}）",
  "常見藥物如 {{Adalat CR®、Covera-HS、Glucotrol XL ER、Concerta®|藥名}}，其中 Glucotrol XL ER 錠片組成包含 {{Hydroxypropyl cellulose|物質}}，其生物惰性成分會在胃腸道中保持完整通過",
  "{{Concerta®|藥名}} 為 {{Methylphenidate HCl|藥名}} 長效劑型（Extended-release），口服後血中濃度會呈現{{雙波峰|名詞}}，兩波峰出現之釋出機制依序為{{速放與滲透壓控釋|名詞}}（第一波峰-速放／第二波峰-滲透壓控釋）",
  "當藥物進入胃腸道時，水分可藉由滲透壓作用滲入錠劑核心，進入核心後被推動層所吸收，推動層吸水膨脹後，將第一層藥物自小孔釋出，此時推動層仍繼續膨脹，不久後將第二層藥物釋出，達到持續釋放之功效",
  "釋放速率：與{{半透膜材質、鐳射小孔孔徑|名詞}}等自身設計有關，與{{胃腸酸鹼值、蠕動|名詞}}等外在因素{{無關|性質}}，釋放速率大多屬於 {{Zero order kinetics|名詞}}（零階次釋放）",
  "圖示（由上而下）：鐳射小孔 → {{藥物層 → 藥物層 → 推動層|名詞}}，外層為半透膜"
]);
t(18, "控釋系統", 135, "matrix-tablets", "親水性基質錠（Matrix tablets）", "親水性基質錠", [
  "將藥物均勻分散於親水性聚合物基質中，當錠劑接觸體液後，基質表面吸水、水合並膨潤形成{{凝膠層|名詞}}，藥物主要經由{{擴散作用及基質溶蝕作用|名詞}}緩慢釋放",
  "可用直接壓錠法製備，或先經造粒後再壓錠；其{{製程與一般錠劑相近|性質}}，但聚合物種類、黏度等級、添加比例及壓錠條件均可能影響藥物釋放速率",
  "當打錠機轉速越快時，藥品顆粒（粉末）受高轉速之影響，可能造成顆粒分布不均、結塊等現象，導致錠片{{重量差異上升|性質}}，錠片{{均勻度、硬度、脆度下降|性質}}"
]);
t(18, "控釋系統", 135, "hydrophilic-matrix-system", "親水基質系統、親水間質系統（Hydrophilic matrix system）", "親水基質系統", [
  "主要控釋材質為 {{HPMC|物質}}（Hydroxypropylmethylcellulose, Hypromellose）（{{非離子型高分子水溶性物質|性質}}），與水接觸後可吸水膨脹形成高黏度膠質層（Gel layer）",
  "此類親水性聚合物具有高度{{水合性|性質}}（Hydration），可緩慢溶解於水中，當錠劑與水接觸後，表面聚合物迅速吸水並溶脹（Swelling），形成高黏性{{凝膠屏障層|名詞}}（膠質層），調控水分進入錠心",
  "藥物釋出機轉：1. {{擴散作用|名詞}}（Diffusion），體液滲入基質後，藥物溶解於水化的凝膠層中，並經由凝膠層依濃度梯度向外擴散釋出；2. {{溶蝕作用|名詞}}（Erosion），外層聚合物持續水合後，聚合物鏈逐漸鬆散、溶解或溶蝕，使包埋於基質中的藥物釋出；3. 藉由控制凝膠層{{厚度與黏度|名詞}}，達到緩慢釋藥目的",
  "可製備成{{單層、雙層及三層|名詞}}之控釋劑型，製備時通常{{不需加入塑化劑|性質}}",
  "材料：應具備{{親水性、水溶性或遇水膨脹|性質}}特性；{{Hypromellose、Poly（ethylene）oxide、Sodium alginate|物質}} 等",
  "備註：凝膠層為控制藥物釋放速率之重要屏障，理想親水性基質應具備在接觸液體時，可{{迅速水合並膨脹成膠體|性質}}（建立擴散阻力）",
  "通常增加{{親水性聚合物|物質}}比例，可增加凝膠層黏度與厚度，使藥物擴散路徑變長或阻力變大，{{降低藥品釋放速率|性質}}"
]);
t(18, "控釋系統", 135, "inert-plastic-matrix", "惰性塑化系統（Inert plastic matrix system）", "惰性塑化系統", [
  "藥物主要經由{{擴散|名詞}}作用自惰性材料中釋出，經過胃腸道時{{不易溶解|性質}}，以{{原型隨糞便排出|名詞}}",
  "服用此類藥物時，{{不需另外與速放錠片共服|性質}}",
  "惰性塑化材料可為{{聚乙烯|物質}}（Polyethylene）、{{聚乙酸乙烯酯|物質}}（Polyvinyl acetate）"
]);
t(18, "控釋系統", 136, "ion-exchange-coated-beads", "離子交換藥物運輸系統、包覆性圓粒", "離子交換／圓粒", [
  "{{離子交換藥物運輸系統|名詞}}：帶正電物質可和帶負電物質形成複合物；腸胃道中藥物釋放速率穩定，但易受{{食物與酸鹼值|名詞}}影響",
  "常使用{{不可溶性樹脂|物質}}（Insoluble resin）材質；為延長控釋效果，可於交換樹脂藥物複合物外加上適當包衣",
  "可利用形成樹脂-藥物複合物特性以{{遮蔽藥品之苦味|名詞}}、達到 Extended-release 效果",
  "{{包覆性圓粒|名詞}}（Coated beads）常用材料：{{Beewax、Glyceryl monostearate、Ethylcellulose|物質}}"
]);
t(18, "補充資料", 136, "insulin-types", "胰島素（Insulin）", "胰島素", [
  "{{超短／速效|名詞}}：{{Lispro insulin、Aspart insulin、Insulin glulisine|藥名}}",
  "{{短效|名詞}}：{{Regular insulin|藥名}}",
  "{{中效|名詞}}：{{NPH、Lente insulin、Isophane insulin、Insulin-zinc|藥名}}",
  "{{長效|名詞}}：{{Glargine insulin、Detemir insulin|藥名}}",
  "備註：胰島素以{{噴霧乾燥法|名詞}}進行藥物乾燥時最容易降解，可改用{{凍晶乾燥法|名詞}}；超短效、短效胰島素可用{{靜脈注射|給藥途徑}}方式給予"
]);
t(18, "補充資料", 136, "high-fiber-tcm-be", "高纖維中藥材、控釋劑型之生體相等性試驗", "中藥材／BE", [
  "{{高纖維中藥材|名詞}}：細碎原料 使用{{剪切力和研磨力|名詞}}；纖維原料 使用{{剪切力|名詞}}；粗粒原料 使用{{衝擊力和壓縮力|名詞}}",
  "{{控釋劑型之生體相等性試驗|名詞}}（節錄自中華藥典第九版）：應分別在{{空腹和餐後|名詞}}條件下，以最高劑量之藥品執行{{單劑量交叉試驗|名詞}}，進行受試藥品和對照藥品比較",
  "進行體內藥品效能評估時，單劑量試驗比多劑量穩定狀態試驗更為{{靈敏|性質}}，尤其是在發生藥品{{突釋現象|名詞}}時，即控釋製劑中活性成分迅速且意外地過早釋放到血液中",
  "低劑量之控釋藥品，基於具有相同之藥物釋放機轉、配方中各成份成比例和溶離曲線相似情況下，低劑量藥品可{{免除其體內試驗|名詞}}之要求",
  "重點：須在{{空腹和餐後|名詞}}分別進行試驗；和速放藥品一樣採用{{單劑量交叉試驗|名詞}}；{{無須|性質}}進行{{多劑量穩定狀態試驗|名詞}}"
]);
t(18, "補充資料", 137, "preformulation", "預配方研究（Preformulation studies）", "預配方研究", [
  "目的：了解原料藥之{{物理化學性質、安定性及與賦形劑之相容性|名詞}}，作為原料藥規格與製劑品質規格制定之參考依據，亦支援臨床前藥效與毒理研究用製劑之研發，進而開發具有科學依據及成效之產品",
  "項目：藥物之物理化學性質（Physical and chemical properties）鑑定與研究：1. {{pH、溶解度、pKa、分配係數|名詞}}",
  "（1）{{水分含量、吸濕性|名詞}}（2）{{熱分析|名詞}}（熱性質、熔點、固態相轉移）（3）{{固態性質|名詞}}：結晶型、非結晶型、多形體及粒徑分布",
  "（4）{{分析方法開發|名詞}}：檢測化合物（API）、不純物（Impurities）及降解產物（Degradation products）之分析方法（5）溶液及固態粉末穩定性（含溫溼度及光照耐受性測試）（6）{{多形體篩選|名詞}}（Polymorph screening）",
  "2. 原料藥{{安定性|名詞}}測試；3. 原料藥規格制訂；4. 臨床前藥效與毒理研究用製劑研發及安定性評估",
  "{{極性|名詞}}大小：{{水 > 酸 > 醇 > 酮 > 酯 > 氯仿 > 醚 > 苯 > 烷類|名詞}}"
]);
t(18, "補充資料", 138, "methylcellulose-functions", "物質與功用：Methylcellulose", "Methylcellulose", [
  "{{錠劑|名詞}}（Tablets）：{{黏合劑|名詞}}（Binders）：提供黏合力，維持打錠時混合物中藥品之均一度，並增加錠劑硬度；{{崩散劑|名詞}}（Disintegrants）：直壓法中，可幫助錠劑崩解",
  "錠劑：{{膜衣劑|名詞}}（Coating agents）：水溶性膜衣材料，可在錠劑外表形成薄膜，達到掩味、保護成分或改變外觀等目的；{{持續釋放修飾劑|名詞}}（Sustained release agents）：可作為親水性基質材料之一，用於製備持續釋放（緩釋）製劑，延緩藥物釋放速率",
  "{{眼用製劑|名詞}}：{{增稠劑|名詞}}（Thickeners）：眼用製劑{{常用|性質}}增稠劑",
  "{{懸液劑、乳劑|名詞}}：{{助懸劑及增稠劑|名詞}}（Suspending & Viscosity-enhancer）：懸浮劑中作為助懸劑，可增加媒液黏度，減緩顆粒沉降速率，防止沉降物結塊；{{乳化劑／保護性膠體|名詞}}（Emulsifiers）：乳劑中作為親水性膠體乳化劑，藉由增加水相（連續相）黏度，使油水兩相較不易分開，增加乳劑安定性",
  "{{微粒與膠囊|名詞}}：{{微膠囊包覆材料|名詞}}（Microencapsulation）：可作為微粒包衣技術之薄膜材料，將藥品（芯材）包覆，防止內容物產生交互作用，並增加藥品穩定性；{{凝膠|名詞}}：可作為親水性凝膠之基劑"
]);
t(18, "補充資料", 138, "other-excipients", "物質與功用：Tartrazine、Aluminum lake、Ethylcellulose、PEO、Sodium alginate", "其他賦形劑", [
  "{{Tartrazine|物質}}（檸檬黃、食用黃色色素四號）：錠劑、膠囊、糖漿、散劑等；{{著色劑|名詞}}（Coloring agent）：增加藥品辨識度，預防給藥錯誤；特定實驗中可作為{{滴定指示劑|名詞}}",
  "{{Aluminum lake|物質}}（鋁麗基）：將水溶性染料吸附或化學結合於不溶性載體鋁鹽基質（常見為{{氫氧化鋁|物質}}，Aluminum hydroxide）所形成之沉澱物，可作為{{著色劑|名詞}}",
  "{{Ethylcellulose|物質}}：{{疏水性、不溶於水|性質}}，常用於製備疏水性基質或作為膜衣材料，限制水分滲透或藥物擴散",
  "{{Polyethylene oxide|物質}}：{{親水性|性質}}物質，遇水後可快速水合形成凝膠層，常用於親水性基質控釋劑型",
  "{{Sodium alginate|物質}}：易溶於水形成黏稠膠體溶液，可作為{{親水基質系統|名詞}}材料之一",
  "冷知識：陰道遞送的 {{Crinone Gel|藥名}} 除了含有 progesterone 外，還添加了 {{Polycarbophil|物質}} 使其具備{{生物黏著|名詞}}之長效作用"
]);
